(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c31"]=[{"id":"00004716","register_sub_id":"101","register_pk":"105706","name":"總持寺御霊殿","kana":"そうじじごれいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50757924,"lng":139.66974521,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0097","desc":"仏殿の後方にあり，後醍醐天皇像を祀る。南から拝殿・幣殿・奥殿が連続し，組物や中備蟇股を備えた社殿建築。奥殿はもこし付の入母屋造，ほぼ方３間の拝殿は，正面の縁を広くして庇柱を建てて縋破風とし，さらに１間向拝を設け，独特な権現造風の構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004716"},{"id":"00004712","register_sub_id":"101","register_pk":"105702","name":"總持寺三松関","kana":"そうじじさんしょうかん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50574663,"lng":139.67338666,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"門 木造、瓦葺、間口6.4m、番所 木造平屋建、瓦葺、建築面積45㎡","structure_material":"門 木造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0093","desc":"東面して建つ切妻造，本瓦葺の１間高麗門で，両側に潜門を設け，北には真壁造，平屋建の小規模な番所が接続し，南には築地塀が延びる。門は総欅造で，細部のつくりも丁寧で充実し，間口６．４ｍの規模を持ち，伽藍の入口を飾るに相応しい雄大な構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004712"},{"id":"00004726","register_sub_id":"101","register_pk":"105716","name":"總持寺三宝殿","kana":"そうじじさんぽうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50443924,"lng":139.67256431,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0107","desc":"低い基壇上に建つ入母屋造，桟瓦葺，妻入の建物で，伽藍の南方にある。１２畳大の前室と，最奥に祭神を祀る２４畳大の部屋からなる。この３方には縁を廻し，前面には円柱をたて，吹放しで舟底天井とした空間と１間の向拝を設ける。独特な構成になる社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004726"},{"id":"00004715","register_sub_id":"101","register_pk":"105705","name":"總持寺紫雲台","kana":"そうじじしうんだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.507252,"lng":139.671692,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積820㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0096","desc":"伽藍中心の東にあり，僧侶・檀信徒等の会見に使われる施設。西面して建つ入母屋造で，軒唐破風付の向拝を設け，４周に縁を廻す。桁行１８間半で，軸部もたちが高く，外観は壮大な構成を見せ，大小に間仕切られた内部は，低平で落ち着いた書院造の空間になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004715"},{"id":"00004720","register_sub_id":"101","register_pk":"105710","name":"總持寺鐘鼓楼","kana":"そうじじしょうくろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.5062276,"lng":139.66961599,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積16㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0101","desc":"放光堂と衆寮の間にある。桁行３間，梁間２間，入母屋造，桟瓦葺の楼造で，１・２階とも平面は同大で通柱とし，１階を通路，化粧屋根裏の２階中央に鐘を吊る。古風な高欄付縁や連子窓などと，禅宗様の双折桟唐戸や花頭窓，吹寄の垂木を巧妙に調和させている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004720"},{"id":"00004721","register_sub_id":"101","register_pk":"105711","name":"總持寺衆寮","kana":"そうじじしょうりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50605717,"lng":139.66980462,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積373㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0102","desc":"伽藍中心部，仏殿の南西に東面して建つ。ほぼ方形平面とした入母屋造，桟瓦葺で，内部は基本的に土間で，壁際に畳敷の床を設け，高く棹縁天井を張る。軒は１軒疎垂木，軸部は角柱，側廻りに舟肘木を配し，舞良戸を多用するなど，簡明な住宅建築の形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004721"},{"id":"00004725","register_sub_id":"101","register_pk":"105715","name":"總持寺鐘楼","kana":"そうじじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.504559,"lng":139.672028,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、瓦葺、建築面積30㎡","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0106","desc":"伽藍の南方，基壇上に建つ切妻造，本瓦葺の吹放し鐘楼。方形の平面で，各辺は中央２，両側１の比で円柱を配し，隅部外側に角柱を斜めにたてる。軸部は挿肘木や貫を巧妙に駆使し，木鼻や蟇股などの装飾細部を要所に設ける。卓越した造形感覚が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004725"},{"id":"00004722","register_sub_id":"101","register_pk":"105712","name":"總持寺大僧堂","kana":"そうじじだいそうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50574255,"lng":139.66983865,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積688㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0103","desc":"衆寮の南，壇正積基壇に東面して建つ。入母屋造，瓦棒銅板葺，内部は土間で，４周側廻りを通路，内側の壁際等には座禅用の畳敷の床を設ける。棹縁天井を張るが，中央２本の独立円柱上には独特な挿肘木を組む。花頭窓，弓欄間など，禅宗様の建築細部を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004722"},{"id":"00004714","register_sub_id":"101","register_pk":"105704","name":"總持寺待鳳館","kana":"そうじじたいほうかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506851,"lng":139.671509,"geo_status":"db","era":"大正4／昭和32移築改造","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1100㎡、正面車寄付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0095","desc":"香積台の北側にある迎賓館施設。主体部は大正４年竣工の尾張徳川家旧書院を移築したもので，これに関東大震災で被災した大正元年竣工の建物の玄関部を附属する。玄関部は唐破風造で，主体部は良材を用いた端正なつくりになり，床・棚の座敷飾も充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004714"},{"id":"00004727","register_sub_id":"101","register_pk":"105717","name":"總持寺放光観音台座","kana":"そうじじひかりかんのんだいざ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50479054,"lng":139.66959827,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、面積43㎡","structure_material":"石造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0108","desc":"伽藍の南西方にある高７尺の花崗岩製台座。基底部は方形平面で，隅に変化をもたせ，その中心に六角形平面で内転びの台座本体を載せる。下部は刳型が繋がり，中央部の各面には梵字を飾り，頂部隅には花弁型装飾をつけるなど，細部まで行き届いた造形になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004727"},{"id":"00004723","register_sub_id":"101","register_pk":"105713","name":"總持寺百間廊下及び門","kana":"そうじじひゃっけんろうかおよびもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50624021,"lng":139.67051858,"geo_status":"db","era":"大正4頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積514㎡、門3所付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0104","desc":"仏殿の南方にある。東西方向の桁行１４２ｍ，梁間３．６ｍで，間に３つの門を設ける。廊下は角柱に舟肘木をのせ，虹梁で繋ぎ，柱間にガラス戸を入れる。各門は桁行１間梁間１間，切妻造で，桟瓦葺屋根を架ける。仏殿前面の空間を効果的に分節する役割をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004723"},{"id":"00004717","register_sub_id":"101","register_pk":"105707","name":"總持寺仏殿（大雄宝殿）","kana":"そうじじぶつでん（だいゆうほうでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506985,"lng":139.669968,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積475㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0098","desc":"伽藍中心部，壇正積基壇上に南面して建つ。方３間，１重もこし付で，入母屋造，本瓦葺，身舎は尾垂木付の３手先組物とする。身舎に比べもこしの柱間を狭くし，内部空間を中央に建つ柱２本で前後に区分するなど，創意工夫を凝らし，内外とも荘厳な構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004717"},{"id":"00004719","register_sub_id":"101","register_pk":"105709","name":"總持寺放光堂","kana":"そうじじほうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506409,"lng":139.669388,"geo_status":"db","era":"安政年間／明治44移築","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政年間","structure":"木造平屋建、瓦葺、建築面積650㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0100","desc":"檀信徒の位牌を祀る建物で，仏殿西方に東面して建つ。入母屋造，桟瓦葺，桁行３０ｍに及ぶ雄大な規模を持つ。内部は正面１間通りを土間とし，床上部は奥中央に仏壇，左右に位牌壇を構え，広大な空間をつくる。各部の彫物や虹梁の絵様に幕末期の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004719"},{"id":"00004724","register_sub_id":"101","register_pk":"105714","name":"總持寺向唐門","kana":"そうじじむかいからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50581635,"lng":139.6708507,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造、檜皮葺、間口6.2m、袖塀63m付","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0105","desc":"仏殿の南，百間廊下の前面にある。切妻造，檜皮葺の四脚門で，前後に唐破風を付ける。木鼻や頭貫など彫りの深い細部を備え，両側面の花狭間や組物間彫物などを精緻につくる。桁行約６ｍと大規模で，両側に築地塀が延び，仏殿前方の重厚な景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004724"},{"id":"00010947","register_sub_id":"101","register_pk":"208918","name":"高部屋神社拝殿及び幣殿","kana":"たかべやじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県伊勢原市下糟屋2202","lat":35.406348,"lng":139.320448,"geo_status":"db","era":"慶応元（1865）","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、茅葺一部銅板葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0220","desc":"本殿前面に建ち、桁行三間梁間二間、入母屋造茅葺の拝殿正面に向拝を付し、背面に幣殿を張出す。特に向拝廻りでは、虹梁の浮彫で亀付の渦紋、菖蒲桁下部から向拝柱頂部に巻き付く龍彫刻など、躍動的で濃密な彫刻で飾り、彫物大工後藤家の力量を発揮している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010947"},{"id":"00010946","register_sub_id":"101","register_pk":"208917","name":"高部屋神社本殿","kana":"たかべやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県伊勢原市下糟屋2202","lat":35.406464,"lng":139.320471,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0219","desc":"境内奥に南面する五間社流造で、三方に縁を廻らして脇障子をたて、前面に浜床を設ける。関東大震災倒壊後の再建時に、身舎柱や正面建具、蟇股、擬宝珠など、正保四年建立の旧社殿の部材を再用する。震災復興造営の一例を示し、県内で希少な五間社社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010946"},{"id":"00010949","register_sub_id":"101","register_pk":"208920","name":"日本基督教団大磯教会門柱及び塀","kana":"にほんきりすときょうだんおおいそきょうかいもんちゅうおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県中郡大磯町大磯字茶屋町1348-1","lat":35.30718976,"lng":139.31375641,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"門柱 コンクリート造、間口2.0m 塀 コンクリート造、総延長5.0m","structure_material":"門柱 コンクリート造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0222","desc":"東海道に面する敷地を画す間口二メートルの門柱一対と、左右に屈曲してのびる塀で、コンクリート造、人造石洗出し仕上げとする。門柱は唐戸面を施し、頂部に三筋の溝を表す。塀は束間にアーチ形の開口を設け、要石風の飾りを付け、アール・デコ風に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010949"},{"id":"00010948","register_sub_id":"101","register_pk":"208919","name":"日本基督教団大磯教会礼拝堂","kana":"にほんきりすときょうだんおおいそきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県中郡大磯町大磯字茶屋町1348-1","lat":35.306991,"lng":139.313707,"geo_status":"db","era":"昭和12／昭和25改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0221","desc":"東海道旧大磯宿の短冊形敷地前寄りに北面して建つ。正面中央と左右に切妻造の張出しを設けて正面に尖塔アーチの玄関を構える。内部は単廊式で奥にゴシック風アーチの祭壇を設ける。外壁は下見板張で、旧宿場の近代的景観に寄与する木造教会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010948"},{"id":"00003204","register_sub_id":"101","register_pk":"104194","name":"日本基督教団横須賀上町教会・付属めぐみ幼稚園","kana":"にほんきりすときょうだんよこすかうわまちきょうかい・ふぞくめぐみようちえん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横須賀市上町2-43","lat":35.27243625,"lng":139.67011517,"geo_status":"db","era":"昭和5頃／昭和25増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積187㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0074","desc":"市中心部に近い住宅街に建設され，上町教会の名で親しまれている教会建築。外装下見板張で，尖頭アーチ型の上げ下げ窓を礼拝堂の各側面に配する。切妻屋根の道路側に設けられた塔屋に十字架を掲げ，歴史的な街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003204"},{"id":"00008428","register_sub_id":"101","register_pk":"134824","name":"寶金剛寺庫裏","kana":"ほうこんごうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県小田原市国府津字八幡上2038他","lat":35.28565845,"lng":139.20813814,"geo_status":"db","era":"寛政12年（1800）／昭和33年改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0168","desc":"旧東海道に近い山裾に所在し、庫裏は境内奥に西面して建つ。桁行一二メートル梁間一二メートル、切妻造桟瓦葺である。南寄りの玄関後方に座敷を並べ、北側に豪壮な軸組を現した大広間を配する。県下に類例の少ない近世の真言宗寺院庫裏である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008428"},{"id":"00014339","register_sub_id":"101","register_pk":"511328","name":"本覚寺大門","kana":"ほんがくじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目303-2","lat":35.31776111,"lng":139.55247222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口3.2m、両袖脇透塀付","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0317","desc":"本堂北の小路に開く門。一間一戸の高麗門で門扉を省略する。切妻造桟瓦葺、両側面に袖壁を付す。軸部は円柱の親柱を立てて内法に梁を渡し、二段の絵様肘木で丸桁を支持する。袖壁は腰を板壁、腰貫上を縦格子窓。境内北辺を画し、寺院の風格を示す木太い門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014339"},{"id":"00014333","register_sub_id":"101","register_pk":"511322","name":"本覚寺客殿","kana":"ほんがくじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31713611,"lng":139.55274167,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0311","desc":"本堂の南東に北面する客殿。入母屋造桟瓦葺の東西棟で、北面東寄りに入母屋造妻入の式台玄関を付し、銅板葺の庇を三方に巡らす。内部は１０畳の座敷を三室並べ、西側を上座敷として床構えを設ける。関東大震災後の再建で、伽藍中枢の景観をつくる広壮な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014333"},{"id":"00014334","register_sub_id":"101","register_pk":"511323","name":"本覚寺庫裏","kana":"ほんがくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31709722,"lng":139.55289167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0312","desc":"客殿の東に北面する庫裏。切妻造桟瓦葺の東西棟で、北面西寄りに入母屋造妻入の玄関を付す。内部は四室を田の字に配し、南西間を床付き座敷とし、南西面に矩折れに廊下が廻る。関東大震災後の再建で、床下や軸部に古材を転用し、伽藍復興の様相を伝える庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014334"},{"id":"00014336","register_sub_id":"101","register_pk":"511325","name":"本覚寺鐘楼","kana":"ほんがくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31751389,"lng":139.55269722,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、瓦葺、面積12㎡","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0314","desc":"本堂の北東に位置する鐘楼。桁行一間、梁間一間、入母屋造桟瓦葺で石積基壇上に建つ。四隅の円柱を腰貫、飛貫、虹梁型頭貫で固め、上部は干支透彫欄間で飾る。組物は出組で軒は二軒繁垂木。関東大震災後の再建で、寺院の歴史的景観をつくる装飾豊富な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014336"},{"id":"00014337","register_sub_id":"101","register_pk":"511326","name":"本覚寺手水舎","kana":"ほんがくじてみずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31735833,"lng":139.55279167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、銅板葺、面積4.6㎡","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0315","desc":"本堂の東に位置する手水舎。桁行一間、梁間一間、切妻造銅板葺。四隅に几帳面取角柱を建て虹梁型頭貫を渡し、獏、唐獅子彫刻の木鼻を架ける。柱上は枠肘木を載せて虹梁を架け、欄間を龍や鳳凰の彫刻で飾る。小規模ながら質の高い彫刻で華やかに飾る手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014337"},{"id":"00014335","register_sub_id":"101","register_pk":"511324","name":"本覚寺分骨堂","kana":"ほんがくじぶんこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31758611,"lng":139.55231389,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0313","desc":"本堂の北に東面し、日蓮の分骨を納める廟堂。桁行１間、梁間１間の身舎に裳階を付し、屋根は宝形造桟瓦葺。内部は身舎内の須弥壇は彩色塗装で荘厳し、後方壇に分骨を納める多宝小塔を安置。関東大震災後の再建で、伽藍中枢に雄大な景観を形成する分骨堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014335"},{"id":"00014332","register_sub_id":"101","register_pk":"511321","name":"本覚寺本堂","kana":"ほんがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31737222,"lng":139.55239722,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0310","desc":"若宮大路の東に位置する日蓮宗寺院本堂。境内中央西寄りに東面し、正面七間、入母屋造桟瓦葺で、正面に軒唐破風の向拝を付す。日蓮宗の伝統的平面ながら、建登せ柱で小屋組はトラスとして軽量化を図る。関東大震災を乗り越えた１０代伊藤平左衛門による本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014332"},{"id":"00014338","register_sub_id":"101","register_pk":"511327","name":"本覚寺楼門","kana":"ほんがくじろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31730556,"lng":139.55311111,"geo_status":"db","era":"安政2年(1855)／明治9年移築・平成25年改修","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造2階建、瓦葺、建築面積30㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0316","desc":"夷堂橋西詰にある伽藍東辺の楼門。桁行三間、梁間二間、入母屋造桟瓦葺で二軒繁垂木、組物は出三斗、中備は間斗束とする。下層両脇間に金剛力士像を安置する。上層は一室の板敷、鏡天井とする。寺院の主要な表構えをつくり、滑川沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014338"},{"id":"00011912","register_sub_id":"101","register_pk":"211077","name":"蓑毛地蔵堂","kana":"みのげじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原724","lat":35.416759,"lng":139.228414,"geo_status":"db","era":"18世紀前半／昭和50年頃改修","year":1705,"year_source":"estimated","year_min":1701,"year_max":1750,"year_label":"18世紀前半","structure":"木造平屋建、鉄板葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-251","desc":"不動堂の北東に東面する三間堂。寄棟造、平入で、一間向拝を付ける。内部は背面中央に六角形の仏壇を置き、両脇は柱間幅に仏壇を構える。組物は拳鼻付大斗絵様肘木で、軒はせがい造。向拝の水引虹梁や木鼻、蟇股、手挟の細部意匠に時代相応の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011912"},{"id":"00011910","register_sub_id":"101","register_pk":"211075","name":"蓑毛大日堂","kana":"みのげだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原721","lat":35.416437,"lng":139.227903,"geo_status":"db","era":"享保14年（1729）","year":1729,"year_source":"db","year_min":1729,"year_max":1729,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-249","desc":"大山の登山口にある敷地の中央に南面して建つ。桁行四間、梁間三間、寄棟造、妻入で、一間向拝を付ける。内部は中央柱を境に外陣、内陣とし、内陣中央間背面に厨子、両脇に仏壇を構える。組物は尾垂木付二手先で、向拝廻りの彫刻は牡丹の手挟など華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011910"},{"id":"00011913","register_sub_id":"101","register_pk":"211078","name":"蓑毛大日堂仁王門","kana":"みのげだいにちどうにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原721","lat":35.416106,"lng":139.227887,"geo_status":"db","era":"19世紀前半","year":1805,"year_source":"estimated","year_min":1801,"year_max":1850,"year_label":"19世紀前半","structure":"木造平屋建、鉄板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-252","desc":"大日堂の南面に建つ仁王門。三間一戸八脚門、入母屋造で、両脇間前方に二王像を安置する。妻飾は虹梁太瓶束笈形付。粽付の円柱を頭貫で固め、台輪上に出三斗とし、正面と背面中央間のみ中備を肩に雲形が付いた蟇股とし、境内の表構えを良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011913"},{"id":"00011911","register_sub_id":"101","register_pk":"211076","name":"蓑毛不動堂","kana":"みのげふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原723","lat":35.416615,"lng":139.228164,"geo_status":"db","era":"17世紀末／昭和50年頃改修","year":1695,"year_source":"estimated","year_min":1688,"year_max":1700,"year_label":"17世紀末","structure":"木造平屋建、銅板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-250","desc":"大日堂北東の小高い場所に建つ。桁行四間、梁間三間、入母屋造、妻入で、一間向拝を付ける。内部は中央柱を境に外陣、内陣とし、内陣中央間背面に厨子を構える。側柱は角柱で上部を丸めて粽状にし、拳鼻付三斗を置く。近年の改造を受けるが境内で最も古い建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011911"},{"id":"00013698","register_sub_id":"101","register_pk":"505219","name":"龍口寺鐘楼","kana":"りゅうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31153333,"lng":139.48966111,"geo_status":"db","era":"明治14年／昭和44年移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造、瓦葺、面積21㎡","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 295","desc":"本堂南東の基壇に南北棟で建つ入母屋造本瓦葺、吹放し形式の鐘楼。長方形平面で規模が大きく、軸部は禅宗様を基調とし、四本の丸柱を内転びに立て、組物は三斗詰組とする。虹梁形内法貫と頭貫の間に蟇股を飾り格天井を張る。意匠簡明ながら力感のある鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013698"},{"id":"00013697","register_sub_id":"101","register_pk":"505217","name":"龍口寺大書院","kana":"りゅうこうじだいしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31131667,"lng":139.48993611,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積399㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 294","desc":"境内南東に建つ。入母屋造妻入の正面に切妻造の平屋と入母屋造庇付の式台を張出す等巧みに屋根を重層させた豪壮な外観とする。一階に大小六室を配し、二階は大広間二室で折上格天井の広闊な空間とし、室ごとに異なる意匠の座敷飾を備えた大規模な接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013697"},{"id":"00013699","register_sub_id":"101","register_pk":"505221","name":"龍口寺手水舎","kana":"りゅうこうじちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31137222,"lng":139.48950278,"geo_status":"db","era":"慶応3年(1867)","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造、瓦葺、面積5.1㎡、水盤付","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 296","desc":"参道東側、妙見堂の向いに南北棟で建つ。桁行一間梁間一間、起り付きの切妻造桟瓦葺。禅宗様を基調とし組物は出組詰組。内転びの四本の角柱や頭貫に地紋彫を施し、木鼻に波に亀、妻飾に丸彫で雲龍の彫刻を飾る等、幕末らしい技巧性が随所にみられる手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013699"},{"id":"00013696","register_sub_id":"101","register_pk":"505215","name":"龍口寺妙見堂","kana":"りゅうこうじみょうけんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31135556,"lng":139.48931111,"geo_status":"db","era":"享保5年(1720)／明治後期改修","year":1720,"year_source":"db","year_min":1720,"year_max":1720,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 293","desc":"本堂に向かう参道の西側に東面して建つ。桁行四間梁間三間、入母屋造、妻入、向拝付で、正面と北側面に縁を廻らす。台輪上に平三斗を組み、軒は二軒繁垂木とする。内部は一室で格天井を張り、後方一間を仏壇として塗装などで荘厳し、妙見菩薩像を安置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013696"},{"id":"00005942","register_sub_id":"101","register_pk":"106927","name":"蒼柴神社拝殿","kana":"あおしじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市悠久町707","lat":37.432415,"lng":138.882401,"geo_status":"db","era":"天明元","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0228","desc":"本殿の前方，石積基壇上に建つ。桁行５間，梁間３間規模，入母屋造，銅板葺で，背面中央に桁行３間，切妻造の幣殿を本殿側に突出す。向拝は３間で中央間を軒唐破風とし，正面に千鳥破風を付けて全体の棟通りを十字形につくるなど特徴的な屋根構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005942"},{"id":"00005941","register_sub_id":"101","register_pk":"106926","name":"蒼柴神社本殿","kana":"あおしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市悠久町707","lat":37.432407,"lng":138.882721,"geo_status":"db","era":"天明元","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積14㎡、覆屋付","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0227","desc":"覆屋内に納まる一間社流造，こけら葺の社殿。長岡藩の作事で，棟札から番匠棟梁安達藤佐衛門吉高らが判明。妻飾りは二重虹梁で，虹梁を出組と蛇腹支輪で持ち出し，中備の唐獅子丸彫で棟を受ける。二手先詰組の腰組や背側面の板羽目の浮彫など装飾面で傑出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005941"},{"id":"00013086","register_sub_id":"101","register_pk":"368256","name":"荒川神社拝殿及び幣殿","kana":"あらかわじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市桃崎浜187","lat":38.14094167,"lng":139.40725,"geo_status":"db","era":"天保12年（1841）／昭和46年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0527","desc":"本殿前面に接続する拝殿及び幣殿は、入母屋造、茅葺形銅板葺で、規模の大きな拝殿の後方に幣殿を張出し、その左右に神饌所と神輿庫を附属する。彫刻豊かな向拝を付け、内部も太い虹梁を四筋架けて大瓶束を立てるなど、重厚な軸部と装飾的細部をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013086"},{"id":"00013085","register_sub_id":"101","register_pk":"368255","name":"荒川神社本殿","kana":"あらかわじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市桃崎浜187","lat":38.14091667,"lng":139.40743333,"geo_status":"db","era":"天保12年（1841）／昭和46年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0526","desc":"北前船で栄えた桃崎浜の高台の境内奥に西面する。建ちの高い一間社流造、茅葺形銅板葺で、正側面に縁を廻らし脇障子をたてる。妻飾を出組で持出し、大瓶束の笈形や虹梁絵様、虹梁上彫刻などを流麗な波涛紋とする。装飾豊かな社殿で北前船交易の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013085"},{"id":"00013706","register_sub_id":"101","register_pk":"505231","name":"淡島神社拝殿","kana":"あわしまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県胎内市新栄町3601-2","lat":38.04726111,"lng":139.40070556,"geo_status":"db","era":"大正15年／昭和5年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 550","desc":"宿場として栄えた旧中条町に位置する。桁行三間、梁間二間、入母屋造桟瓦葺、平入で、正面に一間向拝を付す。向拝の虹梁形頭貫は渦紋を波形とし、龍の彫刻を載せ、木鼻に獏を付すなど、向拝回りに意匠を凝らす。旧宿場町の神社拝殿として景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013706"},{"id":"00005947","register_sub_id":"101","register_pk":"106932","name":"石動神社拝殿","kana":"いするぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市五反田町上ノ山447","lat":37.45923481,"lng":138.77472559,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.7㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0230","desc":"本殿の前方，石基壇上に建つ。正面の柱間２．８ｍ，梁間２．８ｍ規模の入母屋造，銅板葺，平入拝殿。向拝柱に根曲材を用い，正面上部を櫛形に見せているのが特徴で，水引虹梁上部の龍や木鼻の唐獅子の彫物も躍動的で見応えがある。技巧的な技術に優れ，貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005947"},{"id":"00007196","register_sub_id":"101","register_pk":"108178","name":"石動神社拝殿","kana":"いするぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区白新町1-1-11","lat":37.920849,"lng":139.217545,"geo_status":"db","era":"江戸末期／平成16改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0297","desc":"本殿の前方、幣殿を介して繋がる。桁行３間梁間２間で正・側面に高欄付切目縁をまわす。入母屋造桟瓦葺で正面に一間向拝を付ける。正面には桟唐戸、側面には板戸をたて、内部は格天井の１室とする。向拝は前後に拳鼻付の三斗組とし、貘の木鼻を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007196"},{"id":"00005946","register_sub_id":"101","register_pk":"106931","name":"石動神社本殿","kana":"いするぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市五反田町上ノ山447","lat":37.459198,"lng":138.7747785,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0229","desc":"覆屋内に納まる。正面柱間３尺規模の一間社流造，こけら葺で，素木でつくる。軒は二軒繁垂木で，向拝の組物は出組とする。地元の大工高木要助元久によるもので，水引虹梁上部の龍などの彫物に見所があり，海老虹梁に根曲材を用いているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005946"},{"id":"00007195","register_sub_id":"101","register_pk":"108177","name":"石動神社本殿","kana":"いするぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区白新町1-1-11","lat":37.92086962,"lng":139.21745769,"geo_status":"db","era":"寛政8／平成16移築","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.4㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0296","desc":"境内地の中央小高い位置に建つ。切妻造桟瓦葺、桁行２間梁間１間規模。側・背面は横板壁で、縁をまわさない。柱を腰長押、頭貫、台輪で固め、軒桁と虹梁を架す。虹梁上に間斗束をたて、木鼻付大斗肘木を介して棟木を支持する。絵様や蟇股などによく時代を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007195"},{"id":"00007199","register_sub_id":"101","register_pk":"108181","name":"稲荷神社拝殿及び幣殿","kana":"いなりじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3293","lat":37.91559075,"lng":139.22079212,"geo_status":"db","era":"文化12頃／平成13改修","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0300","desc":"本殿の正面に建つ。拝殿は桁行３間梁間２間、入母屋造桟瓦葺で、正面に千鳥破風と一間向拝を付ける。幣殿は拝殿背面中央間と本殿正面を繋ぐ両下造で、桁行３間梁間１間である。本殿と同時に建立された社殿で、いずれも格天井で、天井板に花鳥などを描く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007199"},{"id":"00007198","register_sub_id":"101","register_pk":"108180","name":"稲荷神社本殿","kana":"いなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3293","lat":37.915627,"lng":139.220886,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0299","desc":"境内の東北隅に西面して建つ。桁行３間梁間２間規模の切妻造本殿。正・側面に高欄付の切目縁をまわし、正面に木階を付ける。柱は上部粽付の円柱で、組物は出組とし、支輪をまわす。妻は二重虹梁大瓶束で２段に持ち出す。規模が大きく、見応えのある構造をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007198"},{"id":"00000681","register_sub_id":"101","register_pk":"101671","name":"彌彦神社石橋","kana":"いやひこじんじゃいしばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70502161,"lng":138.82774389,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，幅6.4m，長さ4.5m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0026","desc":"一之鳥居の奥，御手洗川に架けられた石造桁橋で，橋長４．５ｍ，橋幅５．４ｍ，前後に各一間の袖高欄をつける。橋板は７枚石で，緩やかな太鼓橋とする。高欄は，親柱・地覆石・斗・架木ともすべてをひとつの石から彫り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000681"},{"id":"00000669","register_sub_id":"101","register_pk":"101659","name":"彌彦神社石廊下","kana":"いやひこじんじゃいしろうか","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70675864,"lng":138.82583714,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，長さ5.7m，幅3.6m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0014","desc":"本殿と幣殿とを繋ぐ。遷宮式の際にはこの石廊下の上に木造の覆屋を架けた。石積三段で基壇を造り，瑞垣の潜り戸通り筋に三段の石階段を設ける。本殿基壇へは三段の石階段で，また幣殿の裏扉へは五段の石階段で連絡する造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000669"},{"id":"00000668","register_sub_id":"101","register_pk":"101658","name":"彌彦神社一之鳥居","kana":"いやひこじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70491975,"lng":138.82769391,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造，銅板葺，高さ8.5m","structure_material":"木造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0013","desc":"表参道の突き当たり，境内への入口に位置し，手前右手に社号標，左手に制札台を従える。柱間約６ｍ，高さ約８．４ｍの規模で，四脚建て両部鳥居の形式をとる。笠木の屋根は銅板葺，朱塗りで境内地のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000668"},{"id":"00000677","register_sub_id":"101","register_pk":"101667","name":"彌彦神社絵馬殿","kana":"いやひこじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.7056993,"lng":138.8276617,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積132㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0022","desc":"手水舎の手前，やや奥まったところに建つ。反りのある箕甲付入母屋屋根の前後に千鳥破風を構えているところに特徴がある。境内地に隣接して存在した陸上競技場（現在は競輪場）で開催された競技会の入賞額などが掲げられ神社活動の一端を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000677"},{"id":"00000671","register_sub_id":"101","register_pk":"101661","name":"彌彦神社楽舎","kana":"いやひこじんじゃがくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70637904,"lng":138.8274164,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積58㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0016","desc":"舞殿と並び建ち，東に玄関を付す。内部は畳敷で，橋掛廊下入口の左手，舞殿側に奥行一間六畳分の床を高くした楽座を設けている。舞殿と対比して，石積基壇，舟肘木，一軒疎乗木，桟瓦葺など仕様を控えめにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000671"},{"id":"00000682","register_sub_id":"101","register_pk":"101672","name":"彌彦神社狛犬","kana":"いやひこじんじゃこまいぬ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70642756,"lng":138.8265943,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，高さ2.1m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0027","desc":"かっての三之鳥居（現在は随身門）前に建立。伊東忠太の図案により，新海竹太郎が原型を作成している。招魂社系の神社によくみられる両足を突っ張ったタイプの狛犬で，細身で精悍な顔立ちをしている。東京の名石工酒井八右衛門の代表作でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000682"},{"id":"00000676","register_sub_id":"101","register_pk":"101666","name":"彌彦神社鼓楼","kana":"いやひこじんじゃころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70603168,"lng":138.82690729,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積5.9㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0021","desc":"旧社務所に隣接して建てられていたが，昭和３７年新社務所が完成した際に現在地に移築された。桁行梁間とも８尺，軒高１６尺の規模で，高欄付きの縁を回し，箕甲付切妻屋根を架け，下部を袴腰とする。現在も時を告げる鼓楼として機能しつづけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000676"},{"id":"00000675","register_sub_id":"101","register_pk":"101665","name":"彌彦神社斎館（旧勅使館）","kana":"いやひこじんじゃさいかん（きゅうちょくしかん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70663569,"lng":138.82776675,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積149㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0020","desc":"二之鳥居から神馬舎のところで折れた突き当たりに建つ勅使の宿泊施設で，１０畳の書院座敷，１０畳間，２０畳間，６畳二間から成り，西北に湯殿・便所を配し，東で社務所（現在は宝物殿が建つ）に連絡していた。神社の格の高さを示す建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000675"},{"id":"00000672","register_sub_id":"101","register_pk":"101662","name":"彌彦神社参集殿（旧拝観所）","kana":"いやひこじんじゃさんしゅうでん（きゅうはいかんじょ）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70642202,"lng":138.82757934,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積169㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0017","desc":"舞殿での神楽を観覧するための施設。舞殿・楽舎と平行して建ち，東に玄関を付す。北側片廊下の細長い建物で，南面の蔀戸を上げて神楽を拝観する。入母屋造，桟瓦葺，舟肘木など楽舎にほぼ準じた仕様となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000672"},{"id":"00000664","register_sub_id":"101","register_pk":"101654","name":"彌彦神社伺候所","kana":"いやひこじんじゃしこうじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70681621,"lng":138.82603537,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積73㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0009","desc":"神社の宿直所に相当する施設。拝殿の後方右手に位置し，祝詞舎とは渡廊下で連絡し，最奥部は階段となり前庭に通じる。内部は床付１０畳間と１２畳間とから成り，前面に高欄付の縁側を設ける。外見は神饌所と同様のものとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000664"},{"id":"00000662","register_sub_id":"101","register_pk":"101652","name":"彌彦神社神饌所","kana":"いやひこじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70659264,"lng":138.82588796,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積73㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0007","desc":"神社の台所に相当する施設。拝殿の後方左手に位置し，渡廊下で祝詞舎とつながれ，最奥部に階段があり前庭に通じる。入母屋造，平を正面とした寝殿風の建物で，正面４間に蔀戸を建て込み，前面に高欄付の縁を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000662"},{"id":"00000680","register_sub_id":"101","register_pk":"101670","name":"彌彦神社神木石柵","kana":"いやひこじんじゃしんぼくいしだな","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70611634,"lng":138.82791146,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，延長32.8m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0025","desc":"神木は二之鳥居手前右手のやや高地，旧本殿跡の手前に位置する。石柵はこの神木を取り囲むよう不等辺七角形のプランを有し，自然石を積んだ基壇の上に建てられている。柵の高さは１．２ｍで，正面幅１．５ｍ，７段の階段上に石扉２枚を釣り込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000680"},{"id":"00000678","register_sub_id":"101","register_pk":"101668","name":"彌彦神社制札台","kana":"いやひこじんじゃせいさつだい","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70489871,"lng":138.82760034,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造，銅板葺","structure_material":"木造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0023","desc":"一之鳥居に向かって左手前に位置する。石積基壇に建ち，周囲に木製玉垣をめぐらす。柱間１．３５ｍ，棟高約３ｍの規模で，柱より腕木を出して銅板葺切妻屋根を架ける。檜材を用い，腕木を舟肘木と巻斗で支えるなど小規模ながら格の高い仕様をとっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000678"},{"id":"00000667","register_sub_id":"101","register_pk":"101657","name":"彌彦神社摂社草薙神社","kana":"いやひこじんじゃせっしゃくさなぎじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70670812,"lng":138.82688369,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0012","desc":"摂末社８棟のうち焼失した３棟の復興建築のひとつで，横並び８棟のうち向かって左より２棟目にあたる。四代目の草薙神を祭る。今山神社，乙子神社と同規模同型式で，浜床・三方縁・脇障子付，銅板葺，一間社流造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000667"},{"id":"00000674","register_sub_id":"101","register_pk":"101664","name":"彌彦神社手水舎","kana":"いやひこじんじゃちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.7058456,"lng":138.82786224,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積7.０㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0019","desc":"表参道から二之鳥居方向に折れる地点に建つ。銅板葺き反り付き切妻屋根の前後に唐破風を付ける。四方の隅柱に転びをつけ，２本宛の控柱を添わす。天井は格天井，軒は二軒繁乗木で，三斗組を備えるなど舞殿とほぼ同様の仕様としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000674"},{"id":"00000673","register_sub_id":"101","register_pk":"101663","name":"彌彦神社二之鳥居","kana":"いやひこじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70600183,"lng":138.82763365,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，高さ6.4m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0018","desc":"表参道を手水舎のところで左に折れ，しばらく行った石階段の上に建つ。稲田石による石造鳥居で，明神鳥居の形式をとる。柱間４．５ｍ，高さ約６ｍ，笠木石の長さ８．４ｍの規模で，この鳥居から社殿がはじめて望見できることになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000673"},{"id":"00000660","register_sub_id":"101","register_pk":"101650","name":"彌彦神社祝詞舎","kana":"いやひこじんじゃのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70672961,"lng":138.82591536,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積66㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0005","desc":"幣殿と拝殿の間に位置する。屋根は切妻で，棟の一方を幣殿の棟に突きつけ，他方は拝殿屋根の妻に納める。内部は桁行方向に大虹梁を架け，それに梁間方向の虹梁を二重に載せ，化粧屋根裏とする。当初は畳敷であった。神饌所と伺候所との連絡口をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000660"},{"id":"00000661","register_sub_id":"101","register_pk":"101651","name":"彌彦神社拝殿","kana":"いやひこじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70665838,"lng":138.82610438,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積165㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0006","desc":"桁行９間，梁間５間の規模で，入母屋造，妻入とし，後方左右に神饌所と伺候所を従え，前面に唐破風の向拝を付けて正面性を強調した造りとする。内部は桁行方向に大虹梁を架けて無柱の室内を造っている。近代建築家のてがけた神社建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000661"},{"id":"00000659","register_sub_id":"101","register_pk":"101649","name":"彌彦神社幣殿","kana":"いやひこじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70674533,"lng":138.82587279,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積28㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0004","desc":"拝殿・祝詞舎の最奥部に位置し，内部を畳敷とする。平面的には一体であるが，外見上は本殿と同様の三間社流造の形式をとり，祝詞舎側に張りだした奥行一間の階段付大床を納める。背面は石階段と石廊下で本殿と連絡している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000659"},{"id":"00000658","register_sub_id":"101","register_pk":"101648","name":"彌彦神社本殿","kana":"いやひこじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70679212,"lng":138.82576888,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積26㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0003","desc":"明治４５年焼失の再建社殿。再建にあたり，弥彦山を背負う位置に社殿を移す。再建の設計は伊東忠太と桐山平太郎，監督は奥本五一。飾金具の意匠は大江新太郎ら明治神宮造営局のグループがあたる。本殿は焼失前と同様の流造を採用し，屋根は銅板葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000658"},{"id":"00000670","register_sub_id":"101","register_pk":"101660","name":"彌彦神社舞殿","kana":"いやひこじんじゃまいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70640232,"lng":138.8272642,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建橋掛廊下付，銅板葺，建築面積33㎡","structure_material":"木造平屋建橋掛廊下付","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0015","desc":"拝殿に向かう参道中程の右手，摂末社の下段に位置する。亀腹基壇の上に腰組付の高欄を回し，四方を吹き放ちとした舞台建築で，隣接する楽舎から突きだした橋掛廊下を付す。屋根は入母屋造であるが，これのみ扇乗木とし他との違いを際出させている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000670"},{"id":"00000663","register_sub_id":"101","register_pk":"101653","name":"彌彦神社瑞垣・裏門","kana":"いやひこじんじゃみずがき・うらもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70682378,"lng":138.82568966,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造棟門，銅板葺，及び左右瑞垣56.2mよりなる","structure_material":"木造棟門","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0008","desc":"本殿を囲む垣で，正面は幣殿に発し，側面９間建て，正面寄りに潜り門をとり，背面７間建ての中央に裏門を設ける。石製基壇上に建ち，内側に控えの柱をとり，柱間に組格子の狭間を建て込む。屋根は両流れ銅板葺で，裏門は平入唐破風屋根とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000663"},{"id":"00006654","register_sub_id":"101","register_pk":"107637","name":"内島見観音堂","kana":"うちしまみかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区内島見字屋敷付47","lat":37.94025,"lng":139.20137,"geo_status":"db","era":"元治2","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0271","desc":"境内中央北寄りに南面して建つ３間堂。入母屋造桟瓦葺で、１間向拝を付ける。円柱で柱上出組とし、軒は二軒繁垂木。向拝は方柱で唐獅子や龍などの彫刻を飾る。前寄り２間を畳敷の外陣、後寄り２間を内陣とし仏壇を構える。地域の人々の信仰を聚める仏堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006654"},{"id":"00006655","register_sub_id":"101","register_pk":"107638","name":"内島見仁王堂","kana":"うちしまみにおうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市北区内島見字屋敷付47","lat":37.940025,"lng":139.201614,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造、瓦葺、面積19㎡","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0272","desc":"本堂の南に南面して建つ。３間１戸八脚門で、入母屋造桟瓦葺。円柱で出組を置き、軒は二軒繁垂木。両脇間は前１間を吹放ち、後１間を正面のみ腰壁とし他を板壁で囲う。床板敷で、仁王像を安置。天井は彩色画を描く格天井。堂々とした外観が境内景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006655"},{"id":"00007201","register_sub_id":"101","register_pk":"108183","name":"開市神社拝殿","kana":"かいちじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3294-1","lat":37.915176,"lng":139.221039,"geo_status":"db","era":"明治4／昭和44移築改修","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0302","desc":"稲荷神社拝殿の南方に北面して建つ。桁行３間梁間２間、入母屋造桟瓦葺の拝殿で、後に側・背面１間通りが増築された。正面には一間向拝を付けるが、柱や貫、桁を鳥居風に造る。軒をせがい造の一軒繁垂木するなど、社殿としては珍しい仕様を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007201"},{"id":"00005948","register_sub_id":"101","register_pk":"106933","name":"願興寺経蔵","kana":"がんこうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市関原町1-1019","lat":37.45524357,"lng":138.77607547,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、鉄板葺、建築面積21㎡、唐破風向拝付","structure_material":"土蔵造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0233","desc":"石基壇の上に建つ。１辺３．３ｍ，六角形平面の土蔵造経蔵で，屋根は宝形につくり鉄板で葺き，正面に唐破風造の向拝を付ける。地元の大工高木家によるものとされ，向拝の懸魚等の彫物は見事な出来映え。腰部に回した生子鉄板は当初のもので貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005948"},{"id":"00001580","register_sub_id":"101","register_pk":"102570","name":"木揚場教会","kana":"きあげばきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区礎町通1-1957","lat":37.92003838,"lng":139.04895389,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積343㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0052","desc":"浄土真宗大谷派の説教施設で，明治４３年の火災後，大正１５年に再建された。木造で，一階は真宗仏堂とし，前半の二階を一室の道場とする。玄関付・２階建・寄棟造の前半と，これに直交する平屋建で入母屋造の大屋根を組み合わせた特異な形態となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001580"},{"id":"00011093","register_sub_id":"101","register_pk":"205200","name":"敬覚寺本堂","kana":"きょうかくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市江南区酒屋町606-1","lat":37.833063,"lng":139.065263,"geo_status":"db","era":"大正8／平成18改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積327㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0435","desc":"明治三六年の酒屋大火後に再建された。入母屋造桟瓦葺、桁行七間、梁間六間。南面して建ち、正面に一間向拝を付ける。外陣、矢来内、内陣を並べ、内陣は後門形式で左右余間とする。側柱は角柱とし、その他は円柱。典型的な真宗本堂の形式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011093"},{"id":"00011924","register_sub_id":"101","register_pk":"210931","name":"顕法寺本堂","kana":"けんぽうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1154","lat":37.945595,"lng":139.325552,"geo_status":"db","era":"明治43年／平成15年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積418㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-466","desc":"城下町の南端に東面する日蓮宗寺院本堂。桁行五間で、中央間は二間分の間口をもち、広縁・外陣境と外陣・内陣境には直径一・五尺の丸柱を立て虹梁で繋ぐ豪壮な造り。鬼子母神を祀り、細部彫刻にも柘榴を彫る。正面の千鳥破風、向拝の軒唐破風に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011924"},{"id":"00008849","register_sub_id":"101","register_pk":"162292","name":"極楽寺経蔵","kana":"ごくらくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36109428,"lng":138.54709897,"geo_status":"db","era":"文政10年(1827)／万延元年(1860)・平成22年改修","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積47㎡、輪蔵付","structure_material":"土蔵造平屋一部2階建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0358","desc":"庫裏の北に位置し、桁行７．３ｍ梁間５．６ｍ、土蔵造、正面寄棟造、背面切妻造桟瓦葺で、正面側は棟に宝珠を飾り宝形造風に見せる。正面に唐破風造の向拝を付設。内部は前後二室に分け、前室に八角輪蔵を設ける。特殊な形態になる経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008849"},{"id":"00008847","register_sub_id":"101","register_pk":"162290","name":"極楽寺庫裏","kana":"ごくらくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36080678,"lng":138.54706902,"geo_status":"db","era":"江戸後期／平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0356","desc":"本堂の北に東面して建つ。切妻造妻入桟瓦葺で、妻は梁と貫を重ねて飾り、下方に下屋を設ける。東面南寄りが入口で土間とし、その奥の三間×三間半を広い畳敷とし、胴差で固め、小壁は漆喰仕上げで貫を二段に通すなど、伝統的な民家の雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008847"},{"id":"00008851","register_sub_id":"101","register_pk":"162294","name":"極楽寺山門","kana":"ごくらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36127098,"lng":138.54718882,"geo_status":"db","era":"江戸後期／平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、鉄板葺、間口2.7m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0360","desc":"境内の北端に位置し、五平の本柱を間口２．７ｍに、奥行２．１ｍに控柱を立てる。柱を冠木や梁で固め、三斗組で中備に蟇股をおく。妻飾は笈形付大瓶束とし、軒は二軒繁垂木で、切妻造鉄板葺とする。棟を主・控柱の中間とするなど特異な形態になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008851"},{"id":"00008848","register_sub_id":"101","register_pk":"162291","name":"極楽寺書院","kana":"ごくらくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.3607379,"lng":138.54697618,"geo_status":"db","era":"江戸末期／平成22年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0357","desc":"庫裏西奥と本堂を繋ぐ。八畳二室を南北に並べ、それぞれの東面に幅一間の畳廊下を配し、東・西面に榑縁を通す。主室にトコや棚、付書院を構え、次の間境には欄間を飾る。書院に繊細な障子をたて、棹縁を黒漆仕上げとする棹縁天井を張るなど、意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008848"},{"id":"00008850","register_sub_id":"101","register_pk":"162293","name":"極楽寺鐘楼","kana":"ごくらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36104936,"lng":138.54729663,"geo_status":"db","era":"江戸末期／平成22年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積8.7㎡","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0359","desc":"経蔵の東に位置する。南北棟の入母屋造桟瓦葺、方一間の吹放ち鐘楼。高い石積基壇上に礎盤を置き、四方転びに円柱をたて、貫や台輪で固める。柱上三斗組とし、中備に蟇股を飾る。格天井を張り、軒は二軒繁垂木である。堅実なつくりになる鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008850"},{"id":"00008846","register_sub_id":"101","register_pk":"162289","name":"極楽寺本堂","kana":"ごくらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36057917,"lng":138.54701212,"geo_status":"db","era":"宝暦8年(1758)／文化6年(1809)増築、大正7年・平成22年改修","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積343㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0355","desc":"東面して建つ仏堂。正面は入母屋造妻入とし、唐破風造の向拝を付設。切石積基壇上に建ち、舟肘木を置き、腕木を持ち出す。内部は前後二列各四室からなり、正面に奥行二間の広縁を通す。後列南から第二室を内々陣とし須弥壇を構える。大規模な浄土宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008846"},{"id":"00001906","register_sub_id":"101","register_pk":"102896","name":"西永寺経蔵","kana":"さいえいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17834007,"lng":138.74676392,"geo_status":"db","era":"嘉永1頃","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積13㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0108","desc":"本堂前方の左手に位置し，ほぼ北面して建つ。本堂と同時期の再建とみられる。土蔵造，方２間，切妻造，妻入，もと板葺で，正面に切妻造の向拝を付ける。内部は，円柱２本と組物とで仏壇を構え，仏壇両脇から両側面に経棚を配するなど本格的な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001906"},{"id":"00001908","register_sub_id":"101","register_pk":"102898","name":"西永寺庫裏及び廊下","kana":"さいえいじくりおよびろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.1785779,"lng":138.74633317,"geo_status":"db","era":"嘉永元年頃","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積284㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0110","desc":"本堂の北方に建ち，本堂と廊下で結ばれる。本堂と同時期の再建とみられ，庫裏は，切妻造，妻入で，本堂と同様に正面を東にとる。外装，内部は大きく改変を受けてはいるが，庫裏の書院座敷などは当初の型式と格式をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001908"},{"id":"00001907","register_sub_id":"101","register_pk":"102897","name":"西永寺鐘楼","kana":"さいえいじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17847738,"lng":138.74688131,"geo_status":"db","era":"嘉永1頃","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0109","desc":"経蔵の北方，境内に入って直ぐ左手に位置し，高い基壇上に建つ。本堂と同時期の再建とみられる。切妻造，平入，もと茅葺で，４本角柱を内転びに建て，梁中央に載せた地棟状の横架材に鐘を吊す。今も毎日午前１１時に時を告げていることで親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001907"},{"id":"00001905","register_sub_id":"101","register_pk":"102895","name":"西永寺本堂","kana":"さいえいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17836007,"lng":138.7463698,"geo_status":"db","era":"嘉永1","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積480㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0107","desc":"信濃川左岸近くに位置する真宗本堂で，天保６年焼失後の再建になる。棟梁は柏崎の篠田總吉。間口約１９ｍ，入母屋造，平入，向拝１間のやや規模の大きな本堂で，もと茅葺の急勾配屋根をあげる。平面・構造は真宗寺院の法式に則り，内外の彫刻が特に優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001905"},{"id":"00011923","register_sub_id":"101","register_pk":"210930","name":"三光寺本堂","kana":"さんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新発田市諏訪町二丁目390甲","lat":37.945133,"lng":139.329783,"geo_status":"db","era":"大正5年／平成11年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積333㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-465","desc":"寺町通りに西面する浄土宗寺院本堂。外陣の前面に一間幅の板間を取り込み、向拝一間を付け、背面には後堂、開山堂を張り出す。外陣中央間の柱は直径一・四尺の磨き丸太を用い、内陣廻り以外は柱間を虹梁や貫で繋がず内法の高い空間を特色とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011923"},{"id":"00010762","register_sub_id":"101","register_pk":"201597","name":"慈眼寺山門","kana":"じげんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県小千谷市平成二丁目273-1","lat":37.307499,"lng":138.793284,"geo_status":"db","era":"明治25頃／平成18改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、金属板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0423","desc":"境内入口に北面して建つ三間一戸楼門。屋根は入母屋造の正背面に軒唐破風を付ける。禅宗様を基調とし、組物は腰組とも三手先で、上部は尾垂木付とする。板支輪に波紋や鶴などを陽刻し、上部蟇股は龍彫刻とする。安定感ある容姿で細部意匠も見応えのある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010762"},{"id":"00009142","register_sub_id":"101","register_pk":"164695","name":"慈光寺回廊","kana":"じこうじかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63685347,"lng":139.19282141,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山門両側面後間から、南側の東司と北側の禅堂に延びる回廊。桁行総延長27.8メートル梁間1.8メートル、両下造桟瓦葺。正面側は漆喰壁で花頭窓を穿ち、腰に下見板を張る。背面側は内法を吹放つ。境内を結界するとともに、伽藍正面の景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009142"},{"id":"00009143","register_sub_id":"101","register_pk":"164696","name":"慈光寺経蔵","kana":"じこうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63668691,"lng":139.19292849,"geo_status":"db","era":"寛政6年(1794)","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積35㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"伽藍の南西側に北面して建ち、土蔵造、桁行5.8メートル梁間6.0メートル、切妻造桟瓦葺で、正面に下屋を付ける。内部に八角輪蔵を納め、背面の張出しに宮殿を祀る。外壁は上部を横板張、腰を下見板張とする。境内の入口脇にあって、古刹の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009143"},{"id":"00009140","register_sub_id":"101","register_pk":"164693","name":"慈光寺庫裏","kana":"じこうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.6367464,"lng":139.19313372,"geo_status":"db","era":"宝暦9年(1759)／昭和62年改修","year":1759,"year_source":"db","year_min":1759,"year_max":1759,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積374㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本堂南西隅に接続し、北面して建つ。桁行26.7メートル梁間14.1メートル、入母屋造銅板葺で、上手の本堂側に丈室や書院、下手に韋駄天内陣や土間、典座寮などを配し、正面側を土縁とする。江戸後期における曹洞宗寺院の伽藍構成を伝える大型の庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009140"},{"id":"00009144","register_sub_id":"101","register_pk":"164697","name":"慈光寺虚空蔵堂","kana":"じこうじこくうぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市別所字上1318","lat":37.67178151,"lng":139.16853485,"geo_status":"db","era":"宝暦4年(1754)","year":1754,"year_source":"db","year_min":1754,"year_max":1754,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"慈光寺境内から約5キロメートル北西の飛地境内に東面して建つ。正面5間奥行6間、宝形造銅板葺。後半部を畳敷の内陣として正側面3方に縁を廻し、前半部を土間の外陣として木階を設ける。外陣入隅柱間に3間分の梁を架けるなど、特異な内部構成を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009144"},{"id":"00009141","register_sub_id":"101","register_pk":"164694","name":"慈光寺山門","kana":"じこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63679696,"lng":139.19285413,"geo_status":"db","era":"天明5年(1785)","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造、瓦葺、間口5.8m","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"伽藍の西正面中央に建ち、南北に回廊が取付く。3間1戸八脚門、切妻造桟瓦葺で正面左右に四天王像を祀る。軸部は禅宗様を基調とし、組物は三斗で中備蟇股、妻飾は二重虹梁蟇股とする。木部は赤色塗で、素木造を基本とする境内において印象を異にしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009141"},{"id":"00009139","register_sub_id":"101","register_pk":"164692","name":"慈光寺禅堂及び衆寮","kana":"じこうじぜんどうおよびしゅうりょう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63695757,"lng":139.19288685,"geo_status":"db","era":"江戸後期／昭和62年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本堂北西隅に接続し、南面して建つ。桁行24.5メートル梁間11.1メートル、入母屋造銅板葺である。正面1間を土間通路とし、後方の西半を禅堂として須弥壇を中心に単を並べ、東半を衆寮とする。江戸後期における曹洞宗寺院の禅堂の形式をよくとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009139"},{"id":"00009138","register_sub_id":"101","register_pk":"164691","name":"慈光寺本堂","kana":"じこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63692783,"lng":139.19318726,"geo_status":"db","era":"宝暦13年(1763)／昭和30年頃・平成19年改修","year":1763,"year_source":"db","year_min":1763,"year_max":1763,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積526㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山麓の伽藍東奥に西面する。桁行9間梁間8間、入母屋造銅板葺で背面に懸造の開山堂を張出す。平面は6間取の周囲に廊下と縁を廻らし、正面広縁の前半を土間とする。室中の座敷飾りや蟇股等の細部を丁寧につくり、内外ともに整った姿をもつ曹洞宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009138"},{"id":"00005951","register_sub_id":"101","register_pk":"106936","name":"地蔵堂","kana":"じぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市地蔵1-6","lat":37.454796,"lng":138.863098,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積23㎡","structure_material":"煉瓦造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0234","desc":"石基壇の上に建つ。４．８ｍ四方の正方形平面をもつ煉瓦造イギリス積の小堂で，屋根は切妻造，鉄板葺とし，正面に木造の向拝を付ける。小規模ながら，入口や側面の窓はアーチとし，丁寧に造る。軒廻りを斜めに持ち出す煉瓦積技法が使われ貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005951"},{"id":"00015431","register_sub_id":"101","register_pk":"533446","name":"常敬寺山門","kana":"じょうきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目117-1","lat":37.11105833,"lng":138.23831944,"geo_status":"db","era":"江戸後期／昭和30年代改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.3m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0608","desc":"裏寺町通りに東面する薬医門。切妻造桟瓦葺で、五平の本柱上に載せた冠木で男梁を受け、本柱と控柱を貫二段で固める。軒は一軒繁垂木。組物を用いず質実なつくりとするが、妻飾の大振りの蟇股が目を惹く。軸部を弁柄塗で仕上げ、地域が赤門と呼び親しむ山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015431"},{"id":"00015430","register_sub_id":"101","register_pk":"533445","name":"常敬寺鐘楼","kana":"じょうきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目117-1","lat":37.11091389,"lng":138.23779167,"geo_status":"db","era":"寛政4年（1792）／昭和60年頃改修","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0607","desc":"本堂の南東に位置し、基壇上に建つ鐘楼。桁行二間梁間一間入母屋造銅板葺。建ちが高い転びのある角柱を台輪と三段の貫で固め、実肘木付三斗で丸桁を受け、軒は一軒繁垂木とする。中備は西面のみに蟇股を飾る。簡素ながらも境内の歴史的な景観を整える鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015430"},{"id":"00015429","register_sub_id":"101","register_pk":"533444","name":"常敬寺本堂","kana":"じょうきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目117-1","lat":37.11111944,"lng":138.237525,"geo_status":"db","era":"享保16年（1731）／昭和63年改修","year":1731,"year_source":"db","year_min":1731,"year_max":1731,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積308㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0606","desc":"旧高田城下の裏寺町通りに建つ浄土真宗寺院の本堂。桁行一六・四メートル、梁間一六・七メートル、入母屋造銅板葺で正面に向拝を付す。内外陣、左右両余間を配する典型的な真宗本堂平面で、内外陣境には法輪の金箔欄間彫刻を飾る。江戸中期の真宗本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015429"},{"id":"00013073","register_sub_id":"101","register_pk":"368357","name":"浄善寺本堂","kana":"じょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市柿崎区柿崎字仲町6389-1他","lat":37.27746389,"lng":138.39031667,"geo_status":"db","era":"昭和3年／平成5年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積501㎡、鐘塔及び塔屋付","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0514","desc":"市街地に建つ真宗寺院本堂。敷地南に西面して建ち、桁行２７・１メートル規模で、鉄骨鉄筋コンクリート造二階建。正面に尖塔を三基設け、内部は内外陣、余間などからなる真宗本堂の典型を示す。インド風を基調とし、独創的な内外観を実現した本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013073"},{"id":"00013532","register_sub_id":"101","register_pk":"504899","name":"浄福寺本堂","kana":"じょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市柿崎区柿崎字諏訪町6654-1","lat":37.27856389,"lng":138.39213056,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、瓦葺、建築面積395㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0545","desc":"旧北国街道に程近い境内に西面して建つ。防火を意図した鉄筋コンクリート造の真宗本堂で、桁行二四メートル梁間一六メートルとし、エンタシス付の丸柱を配した向拝の両脇に二階建の建屋を張出す独特の外観。コンクリートで重厚かつ優美な内外観をつくり出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013532"},{"id":"00008663","register_sub_id":"101","register_pk":"149384","name":"正法寺観音堂","kana":"しょうぼうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01328453,"lng":138.34542492,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0336","desc":"本堂の西南に東面して建つ。桁行8.3ｍ梁間5.8ｍ、入母屋造桟瓦葺、向拝1間。南半部に東西に内陣と外陣を並べ、北半部に物置と脇間を設ける。内・外陣境に虹梁や木鼻付の組物を備えて間仕切り、内陣には須弥壇を構える。近世境内仏堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008663"},{"id":"00008665","register_sub_id":"101","register_pk":"149386","name":"正法寺蔵","kana":"しょうぼうじくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01321272,"lng":138.3457501,"geo_status":"db","era":"享和2年(1802)／明治30年改修","year":1802,"year_source":"converted","year_min":1802,"year_max":1802,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0338","desc":"本堂と護国蔵の間に東西棟で建つ。桁行5.5ｍ梁間4.5ｍ、置屋根形式の切妻造桟瓦葺、1階北面に下屋を設け出入口とし、2階南面に窓を穿ち、それぞれ掛子塗の両開戸を吊る。外壁は腰を板張とした漆喰仕上げで、開口部まわりを鳥居形に造り、寺紋を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008665"},{"id":"00008664","register_sub_id":"101","register_pk":"149385","name":"正法寺護国蔵","kana":"しょうぼうじごこくくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01304393,"lng":138.34575149,"geo_status":"db","era":"宝永元年(1704)／寛政7年(1795)・明治30年改修","year":1704,"year_source":"converted","year_min":1704,"year_max":1704,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積34㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0337","desc":"本堂の南方、参道に西面する。方5.0ｍ、宝形造桟瓦葺、向拝1間。外壁は漆喰仕上げの大壁造とし、内部は真壁で、板敷、根太天井。中央に仏壇を構え、その側・背面を経典棚とする。軒は台輪上三斗組、中備蟇股。二軒半繁垂木。江戸期の標準的規模の経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008664"},{"id":"00008667","register_sub_id":"101","register_pk":"149388","name":"正法寺山門","kana":"しょうぼうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01295186,"lng":138.34562734,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0340","desc":"境内南面に開く四脚門。切妻造桟瓦葺、正面軒唐破風付。本柱を円柱、控柱を方柱とし、本柱は棟木まで延ばす。虹梁や貫で軸部を固め、平三斗を置き、海老虹梁で繋ぐ。二軒繁垂木。本柱間虹梁上に龍、虹梁や木鼻に霊獣の彫刻を施すなど、表情豊かな装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008667"},{"id":"00008666","register_sub_id":"101","register_pk":"149387","name":"正法寺鐘楼","kana":"しょうぼうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01312623,"lng":138.34552551,"geo_status":"db","era":"文政3年(1820)／明治31年改修","year":1820,"year_source":"converted","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造、瓦葺、面積6.6㎡","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0339","desc":"観音堂の南に位置する、方一間吹放ちの鐘楼。南北棟の入母屋造桟瓦葺。石積基壇上に礎石を置き、方柱を内転びにたて、貫や台輪で固め、三斗組とする。中備は蟇股または蓑束。天井は格天井で格間に絵を描く。二軒半繁垂木。安定した外観になる小規模鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008666"},{"id":"00008662","register_sub_id":"101","register_pk":"149383","name":"正法寺本堂","kana":"しょうぼうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01345823,"lng":138.34555341,"geo_status":"db","era":"享保6年(1721)／明治30年改修","year":1721,"year_source":"converted","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積343㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0335","desc":"境内北寄りに南面して建つ。桁行19ｍ梁間16ｍ、入母屋造桟瓦葺、向拝1間。6間取方丈形式で、正面に広縁、側背面に廊下を付け、背面中央を葺き降ろして開山堂とする。側柱は方柱で、正面大斗肘木、他舟肘木、二軒半繁垂木。近世における曹洞宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008662"},{"id":"00012142","register_sub_id":"101","register_pk":"352941","name":"関山神社宮殿","kana":"せきやまじんじゃくうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県妙高市大字関山4804","lat":36.933772,"lng":138.213395,"geo_status":"db","era":"寛政2年(1790)／文化15年(1818)・昭和35年改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積4.6㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"15-477","desc":"一間社流造、こけら葺で、軒唐破風を付す。三方に切目縁を廻し、脇障子を設ける。組物は三斗、中備蟇股で妻飾は虹梁間斗束。向拝を海老虹梁で繋ぎ、内寄りに手挟を付ける。赤色塗装を基調に向拝柱や正面両折戸を黒漆塗、彫刻を彩色し華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012142"},{"id":"00012141","register_sub_id":"101","register_pk":"352940","name":"関山神社本殿・幣殿・拝殿","kana":"せきやまじんじゃほんでん・へいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県妙高市大字関山4804","lat":36.933769,"lng":138.21351,"geo_status":"db","era":"文政元年(1818)／昭和2年・同45年改修","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"15-476","desc":"妙高山北山麓に東面して建つ。入母屋造妻入で、向唐破風造の向拝一間を付す。桁行七間、梁間三間の堂内に拝殿、幣殿、本殿を納め、後方左右に神饌所・控室を付す特徴的な平面をもつ。尾垂木付二手先組物で随所に彫刻を施し、細部意匠も秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012141"},{"id":"00005793","register_sub_id":"101","register_pk":"106781","name":"世尊寺赤門","kana":"せそんじあかもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97231917,"lng":138.3693252,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.3m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0212","desc":"境内南寄り，本堂の正面に建つ。四脚門，切妻造，桟瓦葺。本柱，控柱ともに円柱，粽付とし，貫で固める。梁行貫上に太瓶束を立てて母屋を受けるが，棟木，母屋，桁を各々海老虹梁で繋ぐ。組物は平三斗。禅宗様を基調とするが，随所に独特な技法と意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005793"},{"id":"00005791","register_sub_id":"101","register_pk":"106779","name":"世尊寺表門","kana":"せそんじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97280938,"lng":138.36926986,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0210","desc":"境内北隅の参道入口で道路に面して建つ。一間の腕木門，切妻造，桟瓦葺。軸部は本柱の前後に控柱を立て，本柱と貫を通して固める。軒は腕木で軒桁を受け，棟木から軒桁に厚板を掛け渡して化粧野地とする。太い柱を使い境内正面の重厚な景観を形成してる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005791"},{"id":"00005795","register_sub_id":"101","register_pk":"106783","name":"世尊寺家財蔵","kana":"せそんじかざいぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.972424,"lng":138.368881,"geo_status":"db","era":"天保2／明治20移築","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造2階建、瓦葺、建築面積30㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0214","desc":"境内のほぼ中央，書院に至る参道に面して建つ。桁行６．５ｍ，梁間４．５ｍ，木造２階建，切妻造，桟瓦葺。南面と西面に下屋が取り付く。外観は正面側を漆喰仕上げ，側面等を下見板張とする。２階の窓は漆喰の額縁を鳥居形に造る丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005795"},{"id":"00005787","register_sub_id":"101","register_pk":"106775","name":"世尊寺書院","kana":"せそんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97244321,"lng":138.36861905,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0209","desc":"本堂西北隅に廊下を介して接続。桁行９ｍ，梁間１０ｍ。木造平屋建，入母屋造，桟瓦葺，側廻りにガラス引戸を建て込む。内部は和室４室をほぼ田の字型に配し，四周に縁を廻らす。鷹の間には２間幅の床の間を設ける。屋根を高くつくり，威厳のある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005787"},{"id":"00005794","register_sub_id":"101","register_pk":"106782","name":"世尊寺宝蔵","kana":"せそんじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.972221,"lng":138.368881,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積14㎡","structure_material":"土蔵造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0213","desc":"境内南端の高台に建つ。桁行３ｍ，梁間４ｍ，土蔵造平屋建，切妻造，屋根は置屋根，桟瓦葺。妻入として庇柱を立て，正面庇を延ばす。庇柱には木鼻付絵様虹梁を通し，柱上には絵様実肘木を置く。扉廻りの漆喰彫刻は技巧的で，特に正面意匠が華やかである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005794"},{"id":"00005782","register_sub_id":"101","register_pk":"106770","name":"世尊寺本堂","kana":"せそんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97233874,"lng":138.36879704,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積301㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0208","desc":"境内南西の山裾に東面して建つ。桁行１７．５ｍ，梁間１５．５ｍの身舎の両側に下屋が付く。木造平屋建，切妻造，桟瓦葺，正面向拝付。側廻りは柱上の絵様実肘木で桁を受け，軒は一軒繁垂木。内部は正面一間を外陣として内陣を広く取る。日蓮宗寺院の大型本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005782"},{"id":"00010574","register_sub_id":"101","register_pk":"201148","name":"善徳寺経堂","kana":"ぜんとくじきょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市吉川区国田51","lat":37.190093,"lng":138.429889,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"15－0409","desc":"土蔵造の経蔵に木軸の覆堂を架け、置屋根状に宝形造瓦葺の屋根を載せる。覆堂は下部を簓子下見板張、上部を開放として飛貫位置に虹梁を組み、南正面に唐破風造の向拝を付す。向拝廻りの鳳凰や龍の彫刻は池山甚太郎の手になり、精緻で躍動感のある優作である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010574"},{"id":"00012518","register_sub_id":"101","register_pk":"367813","name":"善良寺庫裏","kana":"ぜんりょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市西栄町1293","lat":38.051853,"lng":139.400818,"geo_status":"geocoded","era":"天明5年（1785）／昭和前期移築、昭和55年・平成18年改修","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積324㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0492","desc":"本堂北側に東面して建つ。切妻造銅板葺の平屋建で正面南端に切妻造の玄関と渡廊下、背面南端に宝形造の御殿が接続する。内部は玄関から連なる控間付の書院、その奥の小書院、北側の大書院等からなる。下越地方における江戸後期真宗寺院庫裏の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012518"},{"id":"00012517","register_sub_id":"101","register_pk":"367812","name":"善良寺本堂","kana":"ぜんりょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市西栄町1293","lat":38.051853,"lng":139.400818,"geo_status":"geocoded","era":"寛政6年（1794）／明治44年・昭和47年・同62年・平成21年改修","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積327㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0491","desc":"旧中条町中心部の真宗寺院。本堂は東正面の入母屋造銅板葺、向拝一間付。側廻りは出組、中備蟇股、二軒繁垂木とする。正面の中備に大ぶりで独特な形態の蟇股を用い、向拝虹梁の木鼻には躍動感のある龍の彫刻を施す。下越地方の江戸後期真宗本堂の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012517"},{"id":"00013081","register_sub_id":"101","register_pk":"368360","name":"大輪寺経蔵","kana":"だいりんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県胎内市東本町2069-2","lat":38.05576944,"lng":139.40818333,"geo_status":"db","era":"安政4年（1857）／昭和15年・平成15年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造平屋建、金属板葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0522","desc":"境内南東方に南北棟で西面して建つ。置屋根形式の平屋建で、正面に向拝を付け、壁は中塗仕上として腰に下見板を張る。内部は一室とし、東に仏壇を設ける。向拝海老虹梁は葡萄に栗鼠を丸彫りし、また仏壇回りには雲龍の彫刻を付すなど時代の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013081"},{"id":"00013080","register_sub_id":"101","register_pk":"368359","name":"大輪寺庫裏","kana":"だいりんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県胎内市東本町2067-3","lat":38.056,"lng":139.40828889,"geo_status":"db","era":"大正9年／平成15年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階一部平屋建、金属板葺、建築面積370㎡","structure_material":"木造2階一部平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0521","desc":"本堂の東側に、軒唐破風付の表玄関を経て接続し、南北棟の入母屋造で建つ。二列に室を並べ、西列は天井を高めて、東列は二階を設けて衆寮などに供する。表玄関東脇の飯台座は一六畳大の板間とする。建ちの高い近代的な禅院庫裏である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013080"},{"id":"00013083","register_sub_id":"101","register_pk":"368362","name":"大輪寺山門","kana":"だいりんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市東本町2069-2","lat":38.05571111,"lng":139.4079,"geo_status":"db","era":"文久3年（1863）／昭和31年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造2階建、瓦葺、建築面積19㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0524","desc":"境内中軸の中央に建つ二階建鐘楼門。一間一戸門であるが、扉は持たず開放的に作る。下層は成の高い彫刻付きの頭貫を入れて広く開口を取る。上層は三間に割り、台輪を入れて尾垂木付二手先を組み、中備や支輪、頭貫に彫刻を施す。大工の高い技量がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013083"},{"id":"00013084","register_sub_id":"101","register_pk":"368363","name":"大輪寺総門","kana":"だいりんじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市東本町2069-2","lat":38.05528056,"lng":139.40772778,"geo_status":"db","era":"嘉永5年（1852）頃／昭和37年改修","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造、銅板葺、間口3.0m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0525","desc":"米沢街道に面した境内南辺中央に開く四脚門。山門、本堂と直線に並び、境内の中軸を成す。石積基壇上に建ち、本柱を円柱、控柱を角柱とする。切妻造、瓦棒銅板葺の屋根をかける。姿形は端整で、細部意匠にも優れており、境内の正面を飾るに相応しい門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013084"},{"id":"00013082","register_sub_id":"101","register_pk":"368361","name":"大輪寺土蔵","kana":"だいりんじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県胎内市東本町2067-3","lat":38.05563333,"lng":139.40806944,"geo_status":"db","era":"昭和3年／昭和61年移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0523","desc":"庫裏の南方に南北棟で建つ。隣地で鍛冶を営んだ三國家の家財蔵を曳家した。置屋根形式の二階建で、西面して下屋を付ける。漆喰仕上で、腰は海鼠壁、水切りなどには黒漆喰を用いて対比的に見せる。小庇には鶴亀の鏝絵を付けるなど、見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013082"},{"id":"00013079","register_sub_id":"101","register_pk":"368358","name":"大輪寺本堂","kana":"だいりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県胎内市東本町2067-3","lat":38.05609722,"lng":139.40802222,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積337㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0520","desc":"米沢街道沿いの市街地に境内を占める曹洞宗寺院。本堂は境内中軸北寄りに南面して建つ六間取の方丈形式。大間回りを太い虹梁で固め、正面広縁はもとは前半を土間とした。簡明な意匠ながら、要所に彫刻欄間を嵌め、須弥壇回りのみ円柱に出組を組んで荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013079"},{"id":"00010571","register_sub_id":"101","register_pk":"201145","name":"高田別院鐘楼","kana":"たかだべついんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106154,"lng":138.238742,"geo_status":"db","era":"文化3年（1806）／平成18年改修","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造、銅板葺、面積18㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"15－0406","desc":"本堂南東に建つ、方一間、吹放ち形式の鐘楼で、入母屋造銅板葺。切込み接ぎの石積基壇上に建ち、粽付丸柱を礎盤上に立て、腰貫、飛貫、頭貫で固め、台輪を廻し尾垂木付二手先組物を詰組とする。頭貫下には彫刻欄間を嵌める。境内南の景観を構成する鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010571"},{"id":"00010572","register_sub_id":"101","register_pk":"201146","name":"高田別院大門","kana":"たかだべついんだいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106284,"lng":138.239516,"geo_status":"db","era":"文政10年（1827）","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造、瓦葺、面積64㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"15－0407","desc":"本堂正面、道路に面して建つ大型の三間三戸八脚門。禅宗様の尾垂木付三手先組物で軒を大きく張り出し、入母屋造の大屋根を支持する。軸部はケヤキの素木造とし、随所に精緻な彫刻や地紋彫を施して賑やかに飾るなど、高い大工技術を示す。別院に相応しい大門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010572"},{"id":"00010573","register_sub_id":"101","register_pk":"201147","name":"高田別院塀","kana":"たかだべついんへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106282,"lng":138.239529,"geo_status":"db","era":"文政10年（1827）","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造、瓦葺、総延長56m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"15－0408","desc":"大門の左右に取り付き、前方に矩折れにのびる塀で、各々長さ二八メートルとし、切妻造の屋根を架ける。、切石布積基壇に建ち、表側壁面は築地塀形式の白壁に五本の定規筋を引き、裏側は竪板張とする。また大門脇に潜戸を開ける。大門とともに別院の寺格を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010573"},{"id":"00010570","register_sub_id":"101","register_pk":"201144","name":"高田別院本堂","kana":"たかだべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106378,"lng":138.238412,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鋼板葺、建築面積552㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"15－0405","desc":"鉄筋コンクリート造で再建された真宗大谷派別院の本堂。内部の内陣は伝統的な真宗本堂に倣うが、外陣は畳敷の無柱空間とし集会場機能を兼ねる。外観は当時「印度風」と称された特異な形態で、ヴォールト屋根や正面ポーチの尖塔飾りなど特徴的な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010570"},{"id":"00012139","register_sub_id":"101","register_pk":"352938","name":"潮音寺観音堂","kana":"ちょうおんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県小千谷市大字小栗田字岡田962","lat":37.331608,"lng":138.790463,"geo_status":"db","era":"文化14年(1817)","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"15-474","desc":"本堂の北東に南面する。入母屋造の三間堂で軒唐破風付の向拝一間を付す。内陣後方に須弥壇を設け中央に厨子を安置する。組物は三手先で霊鳥や霊獣の彫刻を付し、中備や欄間も濃密に飾る。彫刻は向拝廻りでは躍動感があり、内外陣境は繊細で高い技量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012139"},{"id":"00012140","register_sub_id":"101","register_pk":"352939","name":"潮音寺山門","kana":"ちょうおんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県小千谷市大字小栗田字岡田961","lat":37.33129,"lng":138.790425,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"15-475","desc":"本堂の東方に建つ。間口二・九メートル、切妻造の四脚門。本柱、控柱とも円柱で頭貫と台輪で固める。組物は三斗組、中備は拳鼻付三斗。妻面は本柱から挿肘木と皿斗付巻斗、実肘木で頭貫を受け、妻飾は笈形付大瓶束で、細部まで彫刻を施し整った意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012140"},{"id":"00013068","register_sub_id":"101","register_pk":"368323","name":"長願寺本堂","kana":"ちょうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新発田市下興野字下堅田108","lat":37.93560556,"lng":139.27054444,"geo_status":"db","era":"寛延3年（1750）／大正2年改修","year":1750,"year_source":"db","year_min":1750,"year_max":1750,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積 364㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0509","desc":"市南西にある境内中央に南面して建つ真宗寺院本堂。入母屋造で、正面に三間幅の一間向拝を付し、外陣周囲の広縁を堂内に取り込む。内陣は後門形式で、余間の背後に法衣の間を設け、東面余間脇に堂座敷を張出す。真宗本堂の典型に沿いつつ特異な形式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013068"},{"id":"00007742","register_sub_id":"101","register_pk":"128614","name":"長谷寺内門","kana":"ちょうこくじうちもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97645636,"lng":138.41766462,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.8m、左右袖塀及び潜り付","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"15-0318","desc":"宝蔵の脇にたち、参道と本堂の敷地を画する。袖塀と潜りを脇に付ける一間一戸薬医門。本柱、控柱とも円柱。本柱控柱間の頭貫端が、本柱前方に出て、その上に木鼻付平三斗を梁行に組み、梁を支持する。背面は桁行に三斗詰組。簡素ながら、特殊な架構になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007742"},{"id":"00007738","register_sub_id":"101","register_pk":"108720","name":"長谷寺奥の院","kana":"ちょうこくじおくのいん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97701184,"lng":138.41686479,"geo_status":"db","era":"江戸中期／昭和52改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0314","desc":"観音堂西方の小高い位置に南面して建つ。方三間宝形造。円柱で、平三斗組とし、二軒繁垂木。正・側面中央を開口、正面両脇を格子窓とし、他は板壁。内部は一室で、中央間後寄りに円柱を建て、正面に両開桟唐戸、側面を板壁とし、本尊を安置する。簡明な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007738"},{"id":"00006815","register_sub_id":"101","register_pk":"107797","name":"長谷寺廻廊及び札所","kana":"ちょうこくじかいろうおよびふだしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97684442,"lng":138.4173727,"geo_status":"db","era":"明治前期／平成13改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、鉄板葺、建築面積44㎡","structure_material":"木造平屋一部2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0287","desc":"鐘堂と観音堂を繋ぐ廊下で、参道石段沿いに建つ。南北棟の鉄板葺、幅１．８ｍ長さ１７ｍに及び、参道側を上部横連子腰竪板壁、反対側を全面竪板壁とする。観音堂際を桁行３．７ｍ梁間３．０ｍ２階建、切妻造鉄板葺の札所とし、２階参道側に切子格子の窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006815"},{"id":"00007737","register_sub_id":"101","register_pk":"108719","name":"長谷寺観音堂","kana":"ちょうこくじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.9768152,"lng":138.4175758,"geo_status":"db","era":"元禄4／宝暦10・明治21改修","year":1691,"year_source":"db","year_min":1691,"year_max":1691,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積191㎡、厨子3基付","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0313","desc":"山腹に南面して建つ。規模の大きな五間堂で、外陣及び内陣、脇陣からなり、内陣後方の各間に厨子を安置する。側柱を方柱、入側柱を円柱とする。側まわりは木鼻付平三斗で、内陣正面を支輪付二手先とし、内陣天井に梵字を飾る。江戸中期における密教本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007737"},{"id":"00007739","register_sub_id":"101","register_pk":"108721","name":"長谷寺経蔵","kana":"ちょうこくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97693366,"lng":138.41715222,"geo_status":"db","era":"寛政11","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積24㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0315","desc":"観音堂の西方に東面して建つ。桁行４．９ｍ梁間４．９ｍの土蔵造で、東西棟の桟瓦葺置屋根とし、出入口に切妻造屋根を掛ける。腰板張の白漆喰仕上げとし、開口部上部に唐破風の鏝絵を飾る。内部は一室で、中央に六角輪蔵を備え、輪蔵内に傅大士を祀る壇を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007739"},{"id":"00006813","register_sub_id":"101","register_pk":"107795","name":"長谷寺庫裏","kana":"ちょうこくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.9766009,"lng":138.41789452,"geo_status":"db","era":"江戸後期／昭和53改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺（鉄板仮葺）、建築面積366㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0284","desc":"本堂の東方に南面して建つ、入母屋造妻入茅葺（鉄板仮葺）の建物。桁行１９ｍ梁間１４ｍで、西面南寄りに本堂の玄関、北寄りに２階建の奥茶の間が続く。南面奥行３間を土間とし、その奥を床上とし居室を設ける。太い軸組が、棟高の高い風格ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006813"},{"id":"00006814","register_sub_id":"101","register_pk":"107796","name":"長谷寺護摩堂","kana":"ちょうこくじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97663983,"lng":138.41751633,"geo_status":"db","era":"明治前期／昭和59改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0285","desc":"本堂西方の高い位置、仁王門から観音堂への参道に西面して建つ。桁行７．４ｍ梁間７．１ｍの切妻造桟瓦葺で、南面に本堂への廊を付設する。内部は西正面に広縁、東に南・北２室を設け、南室に不動尊を安置し、護摩壇を置く。仏壇まわりを組物や木鼻などで飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006814"},{"id":"00006817","register_sub_id":"101","register_pk":"107799","name":"長谷寺米蔵","kana":"ちょうこくじこめぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97641151,"lng":138.41788811,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0289","desc":"庫裏の南方、中之蔵の東に、西面して建つ。桁行８．２ｍ梁間４．５ｍ、切妻造桟瓦葺の置屋根で、西面に切妻造桟瓦葺の小規模な蔵前を付ける。外壁は上部を漆喰仕上げとし、腰簓子下見板張。庫裏正面への通路両脇に中之蔵と建ち並び、重厚な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006817"},{"id":"00006966","register_sub_id":"101","register_pk":"107948","name":"長谷寺鐘堂","kana":"ちょうこくじしょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97667473,"lng":138.41748937,"geo_status":"db","era":"江戸中期／Ｍ9移築改修・Ｓ59改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、鉄板葺、建築面積7.4㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0286","desc":"護摩堂の北に隣接して建つ。２層からなる楼門風の鐘堂で、南北棟の入母屋造鉄板葺。下層は桁行３．２ｍ梁間２．３ｍで、廊下として使われる。上層は四周に高欄付の縁をまわし、円柱上に平三斗を組み、二軒繁垂木とする。腰組の龍など秀逸な装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006966"},{"id":"00006967","register_sub_id":"101","register_pk":"107949","name":"長谷寺寺務所","kana":"ちょうこくじてらむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97640668,"lng":138.41807615,"geo_status":"db","era":"安政4／昭和中期・53・平成13改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0290","desc":"庫裏の東方、東西棟で建つ。桁行１９ｍ梁間５．４ｍで、切妻造桟瓦葺とする。柱を半間ごとに建て、貫を数段通す。真壁造で、正・側面等に簓子下見板を張り、軒は出桁を四周にまわす。もとは東半部が家畜小屋、西半部が納屋で、小屋裏に茅を保管した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006967"},{"id":"00006816","register_sub_id":"101","register_pk":"107798","name":"長谷寺中之蔵","kana":"ちょうこくじなかのくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.9764052,"lng":138.41777648,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0288","desc":"本堂の東南に位置する。桁行５．５ｍ梁間４．５ｍ規模の２階建土蔵。切妻造桟瓦葺の置屋根。北面に両開戸をたて、切妻造桟瓦葺の蔵前を付ける。外壁は下見板を張り、一部に漆喰壁を見せる。南面は高い石垣上に建ち、山腹に構える伽藍景観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006816"},{"id":"00007741","register_sub_id":"101","register_pk":"108723","name":"長谷寺仁王門","kana":"ちょうこくじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97604879,"lng":138.41763446,"geo_status":"db","era":"享保3／天明元改修","year":1718,"year_source":"db","year_min":1718,"year_max":1718,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0317","desc":"境内南端の山麓に建つ。三間一戸八脚門、切妻造桟瓦葺。両端間を囲い、後間に仁王像を安置し、中央の通路には扉をたてない。円柱で、禅宗様出組を詰組とし、二軒繁垂木。妻は特徴的な蟇股を使う二重虹梁蟇股。支輪等に彫物を施す。伽藍正面を画する質の高い門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007741"},{"id":"00007740","register_sub_id":"101","register_pk":"108722","name":"長谷寺宝蔵","kana":"ちょうこくじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97639908,"lng":138.41768065,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0316","desc":"観音堂から下がった中段、本堂の西南に位置する。桁行４．５ｍ梁間４．５ｍの土蔵造２階建、東西棟の切妻造妻入桟瓦葺置屋根とし、東正面に切妻造桟瓦葺屋根を掛ける。白漆喰仕上げで、腰に下見板を張る。南・西面は高く石垣を造り、参道石段の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007740"},{"id":"00006812","register_sub_id":"101","register_pk":"107794","name":"長谷寺本堂","kana":"ちょうこくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97667776,"lng":138.41762009,"geo_status":"db","era":"安永6／平成17改修","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造平屋一部2階建、茅葺（銅板仮葺）、建築面積409㎡","structure_material":"木造平屋一部2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0283","desc":"山腹に南面して建つ桁行２１ｍ梁間１４ｍの寄棟造茅葺（鉄板仮葺）の仏堂。非対称の六間取方丈形式を基本に、後列両端室を前後２室に分け、南・西面に広縁、東面に居室を設ける。後列中室に須弥壇を構え、二手先組物や蟇股を飾る。規模壮大な講堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006812"},{"id":"00006818","register_sub_id":"101","register_pk":"107800","name":"長谷寺味噌蔵","kana":"ちょうこくじみそぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97646371,"lng":138.41811184,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積13㎡","structure_material":"土蔵造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0291","desc":"庫裏の東、寺務所の北に建つ。桁行４．５ｍ梁間３．０ｍの妻入で、切妻造桟瓦葺の置屋根とする。中塗仕上げ腰下見板張とし、北と東面に窓を開け、西正面に引込み戸をたて、庇を付ける。内部は板壁で、土間とする。庫裏東面にある生活に関する施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006818"},{"id":"00011920","register_sub_id":"101","register_pk":"210927","name":"長徳寺行在所","kana":"ちょうとくじあんざいしょ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946418,"lng":139.32191,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、銅板葺、建築面積109㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-462","desc":"庫裏の南に接続する。新発田の豪商白勢家の新潟別邸のうち明治天皇のための行在所を移築したもの。一階は玉座と推定される一〇畳を中心に三室を配し、二階に二室を設ける。長押を廻さず数寄屋風意匠とし、床脇や建具などの意匠は大正期らしい瀟洒な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011920"},{"id":"00011919","register_sub_id":"101","register_pk":"210926","name":"長徳寺庫裏","kana":"ちょうとくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946616,"lng":139.322045,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積427㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-461","desc":"本堂の西に廊下を介して接続する。居室部となる二四畳の客間や一二畳のチャノマ等の諸室の奥に三室の新御殿を設け、廊下を隔てて矩折れに古御殿二室を配する。居室部は差鴨居で柱間を広く造り、ダイドコロ上部の梁組に時代相応の特徴を見せる大規模な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011919"},{"id":"00011922","register_sub_id":"101","register_pk":"210929","name":"長徳寺山門及び塀","kana":"ちょうとくじさんもんおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946994,"lng":139.322482,"geo_status":"db","era":"天保12年（1841）","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"山門 木造平屋建、瓦葺、間口3.0m 塀 木造、瓦葺、総延長16m","structure_material":"山門 木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-464","desc":"境内の北面に開く四脚門。切妻造、桟瓦葺で、両脇の潜戸と矩折の塀を付ける。本柱は角柱、控柱は面取角柱とし、腰貫、頭貫で固め、妻面は笈形付き大瓶束で棟木を受ける。細部意匠には江戸後期の特徴が見られ、控柱は腰貫より下に反りを付ける形状とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011922"},{"id":"00011921","register_sub_id":"101","register_pk":"210928","name":"長徳寺鐘楼","kana":"ちょうとくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946817,"lng":139.322584,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-463","desc":"本堂と山門を結ぶ参道の東に南面する。基壇上に建ち、石造礎盤上に几帳面取の角柱を立て、腰貫と虹梁型頭貫で固める。台輪を廻し中備は蟇股、格天井を張る。参道側のみ虹梁絵様は波や菊を彫り、屋根入母屋造の妻飾にも波形彫刻の拝懸魚を飾り正面性を重視する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011921"},{"id":"00011918","register_sub_id":"101","register_pk":"210925","name":"長徳寺本堂","kana":"ちょうとくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946478,"lng":139.322299,"geo_status":"db","era":"嘉永3年（1850）／昭和59年改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積510㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-460","desc":"新発田城跡の南にある真宗大谷派寺院本堂。側背面は舟肘木だが、正面は出組で両端は龍の尾垂木を付け向拝の蟇股や手挟も力量ある彫刻で飾る。典型的な真宗本堂平面で西側の余間脇に床の間・床脇のある座敷二室を付す。天井は小組格天井で、虹梁や蟇股も上質。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011918"},{"id":"00005950","register_sub_id":"101","register_pk":"106935","name":"長福寺山門","kana":"ちょうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市宮本東方町1592","lat":37.442951,"lng":138.743195,"geo_status":"db","era":"安永3","year":1774,"year_source":"db","year_min":1774,"year_max":1774,"year_label":null,"structure":"木造、銅板葺、間口4.5m、袖塀付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0232","desc":"本堂の西方前方に建つ。門口４．５ｍ規模の１間１戸四脚門で，南北の両脇に矩折の袖塀を従える。屋根は切妻造，銅板葺で，軒は二軒繁垂木につくる。骨格は木太く，堂々とした構えをとる。棟札から年代があきらかで，彫物や絵様にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005950"},{"id":"00005949","register_sub_id":"101","register_pk":"106934","name":"長福寺本堂","kana":"ちょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市宮本東方町1592","lat":37.442787,"lng":138.743713,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積449㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0231","desc":"西を正面として建つ。桁行７間，梁間６間規模，入母屋造で，正面に３間の向拝をのばす。内部は梁行を５間とし，前方３間を外陣，後方２間を内陣・余間とし，外陣矢来前の桁行方向に虹梁３本を渡す。地元の大工棟梁高木甚兵衛元綱の作。幕末期真宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005949"},{"id":"00014783","register_sub_id":"101","register_pk":"519041","name":"二王子神社本殿・幣殿及び拝殿","kana":"にのうじじんじゃほんでん・へいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和後","pref":"新潟県","address":"新潟県新発田市田貝2010","lat":37.90508333,"lng":139.45028333,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積306㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0587","desc":"市街地南東の二王子岳の中腹に位置する神社。入母屋造妻入鉄板葺の南北棟で、北面に軒唐破風付の向拝を配す。内部は１室の畳敷とし、上・下拝殿及び幣殿を段差を設けて階段上に並べて格天井を張り、本殿を南へ突出させる。軒柱が周囲を巡る壮大な外観の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014783"},{"id":"00013703","register_sub_id":"101","register_pk":"505229","name":"日本基督教団燕教会","kana":"にほんきりすときょうだんつばめきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県燕市中央通二丁目3361他","lat":37.66584167,"lng":138.93013333,"geo_status":"db","era":"昭和5年／昭和39年・同45年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積206㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 547","desc":"市の中心部に位置。木造二階建切妻造桟瓦葺。西面し、奥に細長い平面を持ち、前面に便所、背後に倉庫を突出する。一階に旧保育園、二階に礼拝所を配し、外壁は下見板張で二階に半円アーチ窓を並べ、正面妻に十字架を掲げる。地域の景観を形成する木造教会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013703"},{"id":"00007197","register_sub_id":"101","register_pk":"108179","name":"古峯神社本殿","kana":"ふるみねじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区白新町1-1-11","lat":37.920746,"lng":139.21750614,"geo_status":"db","era":"天保8／明治期移築","year":1837,"year_source":"db","year_min":1837,"year_max":1837,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0298","desc":"覆屋内に東面して建つ。軒唐破風付の隅木入一間社春日造で、両側面に千鳥破風を付ける。屋根こけら葺。組物は出組とし、支輪を四周にまわし、妻は二重虹梁大瓶束とする。軸部等に地紋彫、扉や壁面には浮彫、向拝に龍などの丸彫を施し、彫物装飾で社殿を充たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007197"},{"id":"00006821","register_sub_id":"101","register_pk":"107803","name":"本光寺大門","kana":"ほんこうじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00592984,"lng":138.27968276,"geo_status":"db","era":"弘化3／昭和48移築","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造、瓦葺、間口2.5m、両脇潜付","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0294","desc":"通りに面して建つ、潜り付１間薬医門。切妻造桟瓦葺。本柱を粽付円柱、控えを方柱とし、礎盤上に建てる。妻面に虹梁状の貫を２段に架し、大瓶束や木鼻、笈形、立ち上がりの大きい海老虹梁などを用い、見応えのある架構を造る。禅宗様を意識した秀逸な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006821"},{"id":"00006820","register_sub_id":"101","register_pk":"107802","name":"本光寺鐘楼","kana":"ほんこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00590615,"lng":138.27974484,"geo_status":"db","era":"明治19／昭和48移築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、面積6.5㎡","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0293","desc":"本堂の東北に東西棟で建つ。方１間吹放ち鐘楼で、基壇上に内転びのある方柱を建て、腰貫と内法貫を入れ、虹梁状の頭貫と台輪で固める。組物は平三斗組、中備は木鼻付平三斗。妻は虹梁大瓶束で、軒を二軒繁垂木とする。伝統的な様式になる標準的な吹放ち鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006820"},{"id":"00006822","register_sub_id":"101","register_pk":"107804","name":"本光寺塀","kana":"ほんこうじへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00596036,"lng":138.27969092,"geo_status":"db","era":"江戸末期／昭和48移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長14m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0295","desc":"大門の東西、通り沿いに建つ。東側折曲り延長９．０ｍ西側折曲り延長４．８ｍで、総高２ｍに及ぶ。高さ１ｍの凝灰岩基礎上に土台を置き、柱を建て貫を通し、漆喰仕上げ真壁とする。腕木により桁を介し板軒を支持し、桟瓦を葺く。落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006822"},{"id":"00006819","register_sub_id":"101","register_pk":"107801","name":"本光寺本堂","kana":"ほんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00577831,"lng":138.27974463,"geo_status":"db","era":"江戸後期／昭和10改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積177㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0292","desc":"通りの南側に占める敷地のほぼ中央に位置し、北面して建つ。桁行１１ｍの３間堂で、切妻造桟瓦葺。正面から広縁、外陣、矢来内とし、その奥に内陣と左右余間を配する標準的な浄土真宗本堂平面になる。外観は簡明ながら、組物や欄間など丁寧な造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006819"},{"id":"00013977","register_sub_id":"101","register_pk":"508237","name":"本成寺表玄関","kana":"ほんじょうじおもてげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62245,"lng":138.94462778,"geo_status":"db","era":"明治28年頃／昭和前期・平成23年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0558","desc":"客殿と庫裏の間を繋ぐ桟瓦葺の南北棟である。東面中央の玄関唐破風には懸魚を三つ飾る。内部は、表玄関の間一〇畳の北が小会議室で、南の応接室は昭和前期改装の洋室である。西には南北廊下を通して客殿と庫裏を結ぶ。重厚な式台玄関が境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013977"},{"id":"00013975","register_sub_id":"101","register_pk":"508235","name":"本成寺客殿","kana":"ほんじょうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62263333,"lng":138.944725,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積571㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0556","desc":"本堂南西に東面して建つ入母屋造の桟瓦葺で向拝を付す。桁行七間の中央三間が格天井の内陣で背面中央に須弥壇を置き脇壇を設ける。南北両脇は棹縁天井の外陣で、四周に縁を廻らせ、北の寂光殿へ渡廊下が延びる。内部は柱を減らして広く伸びやかな空間をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013975"},{"id":"00013976","register_sub_id":"101","register_pk":"508236","name":"本成寺庫裏","kana":"ほんじょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62229722,"lng":138.94452222,"geo_status":"db","era":"明治28年／昭和56年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積567㎡","structure_material":"木造平屋一部2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0557","desc":"境内南西に建つ入母屋造桟瓦葺で、東正面に妻を見せ、北寄りに内玄関、南に御大途玄関を開く。床上中央の囲炉裏の間は二四畳の二室で、前身本堂の柱を削り直した夫婦柱が立つ。南側の寺務所は元は土間であった。客殿南に並び建ち、境内空間を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013976"},{"id":"00013978","register_sub_id":"101","register_pk":"508238","name":"本成寺大書院","kana":"ほんじょうじだいしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62263611,"lng":138.94441389,"geo_status":"db","era":"明治32年頃／平成23年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0559","desc":"客殿の背面と太鼓橋で結ぶ切妻造桟瓦葺である。庫裏の北に中庭を介して接続する。中庭に面して一二間半三室からなる対面の間、中庭西に一〇畳二室の内対面の間を配す。中庭側と内対面の間の南から西に土縁がつくのは雪国らしい。落着いた造作の座敷群である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013978"},{"id":"00013974","register_sub_id":"101","register_pk":"508234","name":"本成寺本堂","kana":"ほんじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62291111,"lng":138.94537778,"geo_status":"db","era":"明治36年／昭和32年・平成11年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積881㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0555","desc":"三条市街に所在する法華宗陣門流の総本山である。入母屋造の本瓦型金属板葺で、正面の三間向拝は唐破風を三つの懸魚で飾る。内陣は凸型に突出して床を一段高める。背面の突出は後方の真骨塔の遙拝所である。優秀な彫刻を各所に飾る富山大工による壮大な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013974"},{"id":"00009932","register_sub_id":"101","register_pk":"196079","name":"宮川神社拝殿及び幣殿","kana":"みやがわじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県柏崎市大字宮川字向山4027","lat":37.45316677,"lng":138.61205032,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"15 － 0388","desc":"三間四方で正面に一間向拝の付く拝殿と、間口一間で両側に下屋の取付く幣殿からなる。拝殿の組物は出組、中備に蟇股を入れ、向拝虹梁上には龍の丸彫を飾る。拝殿妻飾の虹梁に彫られた左右対称形の渦紋や、蟇股、肘木の繰形などに、棟梁の篠田宗吉の特徴が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009932"},{"id":"00009931","register_sub_id":"101","register_pk":"196078","name":"宮川神社本殿","kana":"みやがわじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市大字宮川字向山4027","lat":37.4531325,"lng":138.61198388,"geo_status":"db","era":"文政12","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積4.5㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"15 － 0387","desc":"一間社流造こけら葺の本殿。身舎正面は方立と彫刻付の小脇板を構えて扉を省き、内部に木階二級を設け、その奥を内陣と内々陣に仕切る。組物二手先で中備を蟇股とし、妻は大瓶束に雲紋をあしらった笈形を付ける。頭貫や彫刻の意匠に凝り、時代相応の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009931"},{"id":"00005264","register_sub_id":"101","register_pk":"106252","name":"妙光寺三重小塔","kana":"みょうこうじさんじゅうのしょうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市西蒲区角田浜1056","lat":37.7974558,"lng":138.83017548,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造三重塔、金属板葺、建築面積1.0㎡","structure_material":"木造三重塔","registered":"2006.03.02(平成18.03.02)","register_no":"15 － 0197","desc":"参道脇の池泉の北岸に建つ木造三重，チタン葺の高さ５．２ｍの小塔である。柱を円柱とし，軒を尾垂木を付けた四手先組物で支え，三手と四手の間を軒支輪とし，台輪中央の中備に蟇股を置く。各重に高欄付きの縁を廻す。建設当初の姿を留め，境内景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005264"},{"id":"00005265","register_sub_id":"101","register_pk":"106253","name":"妙光寺山門","kana":"みょうこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市西蒲区角田浜1056","lat":37.79721241,"lng":138.83027527,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"15 － 0198","desc":"本堂と中門を結ぶ軸線上に建つ。桁行１５尺，梁間１３尺とし，切妻造，桟瓦葺の四脚門で，門扉を付けない。出組，実肘木で丸桁を受け，妻側は二重虹梁蟇股の上に大瓶束をのせ，棟木を支える。頭貫の象鼻や獅子鼻，軒支輪の彫物等に江戸後期の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005265"},{"id":"00005266","register_sub_id":"101","register_pk":"106254","name":"妙光寺鐘楼","kana":"みょうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区角田浜1056","lat":37.7971505,"lng":138.83011102,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、面積12㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"15 － 0199","desc":"境内南側の山際に建つ。桁行１０．４尺，梁間９．７尺で，入母屋造，桟瓦葺とし，角柱四本を内転びに建て，飛貫や頭貫で固める。出三斗で軒桁を支え，中備を蟇股とする。格天井や懸魚等に意匠的特色が見られ，三重小塔，山門と共に境内の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005266"},{"id":"00008437","register_sub_id":"101","register_pk":"134833","name":"楞厳寺山門","kana":"りょうごんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市柿崎区芋島字経ケ峯2727-2","lat":37.24412541,"lng":138.4511316,"geo_status":"db","era":"江戸中期／元文元年（1736）改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、茅葺、間口3.5m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0331","desc":"本堂の南方に南面して建つ、切妻造茅葺の四脚門。本柱と袖柱を地覆と腰長押、頭貫で固め、柱上に大斗を置き、虹梁を架け、中央に蟇股を載せ、棟木を支持。冠木上中央に間斗束を置く。軒は二軒繁垂木。床は四半石敷で、両開戸をたてる。雄渾な雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008437"},{"id":"00008436","register_sub_id":"101","register_pk":"134832","name":"楞厳寺本堂","kana":"りょうごんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市柿崎区芋島字経ケ峯2727-1","lat":37.24461941,"lng":138.45126633,"geo_status":"db","era":"江戸中期／昭和32年・平成20年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積368㎡、鐘楼付","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0330","desc":"南面して建つ、桁行二二メートル梁間一六メートル、入母屋造銅板葺の本堂。八間取方丈形式とし、正面に大縁と露縁を通す。側まわりは方柱で、舟肘木を置く。内陣は正面を円柱とし、上部に出組を飾り、来迎壁や須弥壇等を構える。江戸中期の標準的な曹洞宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008436"},{"id":"00002902","register_sub_id":"101","register_pk":"103892","name":"蓮華峰寺大門","kana":"れんげぶじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83562744,"lng":138.28779664,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、高さ3.7m","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0120","desc":"蓮華峰寺は佐渡島にある真言宗の古刹である。大門は切石を積み上げた高さ約三．七メートルの東西一対の石柱で，西側の石柱に「昭和三年八月一日 青柳貞秀建之」の刻銘がある。北からの参道の入口にあり，寺の入口を示すランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002902"},{"id":"00002910","register_sub_id":"101","register_pk":"103900","name":"蓮華峰寺御霊屋覆屋","kana":"れんげぶじおたまやおおいや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.8365661,"lng":138.28825638,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0129","desc":"東照宮と台徳院御霊屋の覆屋で，切妻造桟瓦葺。側背面三方は板壁で，現状は正面も格子窓付きの板壁で閉ざすが，これは最近のもので，もとは正面開放であった。先々代住職が大正期に建てたと伝える。御霊屋とともに保存を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002910"},{"id":"00002913","register_sub_id":"101","register_pk":"103903","name":"蓮華峰寺唐門","kana":"れんげぶじからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83499272,"lng":138.28806386,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積8.54㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0132","desc":"金堂前庭と庫裏客殿の一郭を分ける四脚門で，唐破風はない。親柱を棟木近くまで立ち上げ，側柱とは海老虹梁で繋ぐ禅宗様四脚門の様式で，様式上江戸時代中期の建築と見られる。親柱筋の中央上部には成の高い蟇股を入れるなど雄大な意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002913"},{"id":"00002914","register_sub_id":"101","register_pk":"103904","name":"蓮華峰寺客殿","kana":"れんげぶじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.835396,"lng":138.28804,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0133","desc":"金堂南方にあり，前身客殿が明治３０年の水害で倒壊した後に建てられた。桁行２４．６メートル，梁間１６．１メートルの山内最大の建築で内部は８室構成で，それと矩の手に巡る広縁からなる。近代の大規模客殿として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002914"},{"id":"00002905","register_sub_id":"101","register_pk":"103895","name":"蓮華峰寺経蔵","kana":"れんげぶじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83604591,"lng":138.28785673,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造平屋建、瓦葺、建築面積34㎡","structure_material":"土蔵造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0124","desc":"鐘楼堂北側に建つ切妻造，桟瓦葺，妻入の土蔵で，正面に１間の向拝を付ける。内部は板張で，化粧棟木に半間毎の化粧垂木をあらわす。向拝細部の様式から江戸時代中期の建築と見られ，近世寺院に見られる土蔵造経蔵の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002905"},{"id":"00002915","register_sub_id":"101","register_pk":"103905","name":"蓮華峰寺護摩堂","kana":"れんげぶじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83560196,"lng":138.287994,"geo_status":"db","era":"元禄3","year":1690,"year_source":"db","year_min":1690,"year_max":1690,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0134","desc":"客殿北側に渡り廊下で接続する入母屋造妻入，桟瓦葺の三間堂。棟札によって元禄３年の建築年代が判明する。組物を出組とし，軒を二軒繁垂木とする。蓮華峰寺の三間堂の中では年代的にも技法的にも中庸を占めるものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002915"},{"id":"00002903","register_sub_id":"101","register_pk":"103893","name":"蓮華峰寺地蔵堂","kana":"れんげぶじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83591727,"lng":138.28851345,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0121","desc":"金堂東方にある末寺宝積院の本堂で，佐渡四国古遍路第一番札所。建物は正面３間，側面３間，屋根宝形造，桟瓦葺で，背面軒下に仏壇を張り出す。棟札により明治２６年の建築が明らかである。蓮華峰寺伽藍及び地方の札所を構成する要素として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002903"},{"id":"00005077","register_sub_id":"101","register_pk":"106067","name":"蓮華峰寺鐘楼堂","kana":"れんげぶじしょうろうどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83607962,"lng":138.28825876,"geo_status":"db","era":"慶長20","year":1615,"year_source":"db","year_min":1615,"year_max":1615,"year_label":null,"structure":"木造2階建、銅板葺、建築面積19㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0123","desc":"金堂北東の台地上にある袴腰付きの鐘楼。上層は桁行３間，梁間２間で四方に腰組付の縁を巡らせ，組物は出組で寄棟造，茅葺形銅板葺の屋根を掛ける。正当な手法からなる鐘楼で，幕末期の改造は大きいが，なお桃山建築の特徴を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005077"},{"id":"00002909","register_sub_id":"101","register_pk":"103899","name":"蓮華峰寺台徳院御霊屋","kana":"れんげぶじだいとくいんおたまや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.8366461,"lng":138.28815652,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、柿葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0128","desc":"台徳院御霊屋は，東照宮と同じくこけら葺の一間社であるが，東照宮は屋根が入母屋造であるのに対し，切妻造妻入である。軸部や軒の彫刻や彩色，組物の形式等は東照宮と同様で，同時期に建てられたと見られる。小規模ながら精緻な技巧を凝らし，残りも良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002909"},{"id":"00002908","register_sub_id":"101","register_pk":"103898","name":"蓮華峰寺東照宮","kana":"れんげぶじとうしょうぐう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83655341,"lng":138.28829063,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、柿葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0127","desc":"八角堂北側の覆屋内に台徳院霊屋と東照宮が左右に並んで建つ。東照宮はこけら葺の一間社で，軸部の外部全体を彫刻，彩色で埋め，組物を三手先とし，軒も彫刻付きの板軒（二軒）とするなど，豪華な仕様を採る。彫刻絵様から江戸時代中期の建築と見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002908"},{"id":"00002916","register_sub_id":"101","register_pk":"103906","name":"蓮華峰寺独鈷堂","kana":"れんげぶじどっこどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.835701,"lng":138.286636,"geo_status":"db","era":"元和8","year":1622,"year_source":"db","year_min":1622,"year_max":1622,"year_label":null,"structure":"石造平屋建、石葺、建築面積3.0㎡","structure_material":"石造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0135","desc":"金堂前庭から西の谷を分け入った奥にある泉の傍に建つ切妻造妻入の石祠。昭和５４年に水害で倒壊し修理されているが，この時に採用されなかった部材に元和八年の刻銘がある。正面を三間に割り，石棟の両端には鬼面を現わすなど，丁寧な仕事を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002916"},{"id":"00002904","register_sub_id":"101","register_pk":"103894","name":"蓮華峰寺仁王門","kana":"れんげぶじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83586515,"lng":138.28805226,"geo_status":"db","era":"文政5","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0122","desc":"金堂東南にある東を正面とする八脚門で両脇間後方に金剛力士を収める。入母屋造桟瓦葺で総円柱，組物二手先の格式の高い細部を持つ。石製の礎盤１２個にはそれぞれ寄進者の名前が刻まれており，崇敬を集めた様子が偲ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002904"},{"id":"00002906","register_sub_id":"101","register_pk":"103896","name":"蓮華峰寺八角堂","kana":"れんげぶじはっかくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83633634,"lng":138.28830542,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0125","desc":"経蔵北側に建つ銅板葺の八角円堂。江戸時代中期の建築と見られ，内部は柱間毎の三角形の小室に分かれ，それぞれに宮殿を収める。軒の組物は絵様肘木や彫刻を多用した三手先で，全体で雲中の竜を表現するなど異色の造形を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002906"},{"id":"00002907","register_sub_id":"101","register_pk":"103897","name":"蓮華峰寺八祖堂","kana":"れんげぶじはっそどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83649876,"lng":138.28797352,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0126","desc":"金堂北側の丘の上に立つ入母屋造，茅葺形銅板葺の三間堂。組物を異例の五手先とするため，茅葺形と相俟って特に屋根の大きい印象を受ける。内部も虹梁や太瓶束等からなる架構を見せ，全体に彩色を施した迫力のあるもので，八角堂とともに異色の造形を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002907"},{"id":"00002912","register_sub_id":"101","register_pk":"103902","name":"蓮華峰寺密厳堂","kana":"れんげぶじみつげんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83627386,"lng":138.28729366,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0131","desc":"金堂西方に建つ三間堂で，佐渡四国六番札所。宝形造桟瓦葺で，前面に一間向拝を付ける。天保１５年の建築と伝え，小規模な堂であるが組物を出組とし，内部の支輪等に彫刻をあしらうなど，密度の高い仕事である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002912"},{"id":"00002911","register_sub_id":"101","register_pk":"103901","name":"蓮華峰寺無明橋","kana":"れんげぶじむみょうばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83660497,"lng":138.28717952,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造桁橋、橋長4.1m、幅員1.6m","structure_material":"石造桁橋","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0130","desc":"奥院弘法堂に至る参道にある石造桁橋。寛政１２年(１８００)の資料に「奥之院御廟之橋」として出てくる。反りをもち、中央の橋脚上の桁受で３筋の橋桁を受ける構造で，３６枚の橋板裏にそれぞれ梵字を刻む。意匠だけでなく技法にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002911"},{"id":"00001909","register_sub_id":"101","register_pk":"102899","name":"西永寺六和亭（旧永徳寺本堂）","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17874536,"lng":138.74651559,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0111","desc":"庫裏の前方に西面して建つ。もと境内に在った別の寺院本堂で，昭和１０年代に廃寺となった後，現在地に移築された。正面２間半，奥行４間の寄棟造，妻入で，内部は内陣，外陣に分かれ，梁などに絵様を彫るなど小規模ながら整った御堂になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001909"},{"id":"00000679","register_sub_id":"101","register_pk":"101669","name":"彌彦神社神符授与所","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70577465,"lng":138.82801627,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積41㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0024","desc":"表参道が二之鳥居に向かって折れる地点の手前右手，手水舎の向かいに建つ。瓦葺切妻屋根，舟肘木仕様の建物で，銅板葺の裳階は後補である。神苑沿いの東参道からのアプローチを考慮して妻面の構成に意を凝らした造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000679"},{"id":"00000665","register_sub_id":"101","register_pk":"101655","name":"彌彦神社摂社乙子神社","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.7066673,"lng":138.82698942,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0010","desc":"摂末社８棟のうち焼失した３棟の復興建築のひとつで，横並び８棟（右端の十柱神社は重要文化財）のうち向かって左より５棟目にあたる。焼失前と同様形式の一間社流造で，浜床・三方縁・脇障子付の社殿になり，屋根を銅板葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000665"},{"id":"00000666","register_sub_id":"101","register_pk":"101656","name":"彌彦神社摂社今山神社","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70669137,"lng":138.82692138,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0011","desc":"摂末社８棟のうち焼失した３棟の復興建築のひとつで，横並び８棟のうち向かって左より３棟目にあたる。五代目の今山大神を祭る。七代目を祭る乙子神社と同規模同型式で，浜床・三方縁・脇障子付き，銅板葺，一間社流造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000666"},{"id":"00007200","register_sub_id":"101","register_pk":"108182","name":"稲荷神社神輿庫","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3293","lat":37.91548643,"lng":139.22094043,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0301","desc":"本殿の南方に位置する。桁行４．５ｍ梁間３．６ｍの切妻造桟瓦葺で、正面に一間向拝を付ける。方柱で三斗組とし、妻は二重虹梁蟇股。軒は一軒疎垂木。内部は床モルタルの１室で、格天井の天井板には花鳥を描く。切妻社殿風の特異な外観になる神輿庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007200"},{"id":"00005270","register_sub_id":"101","register_pk":"106258","name":"有礒正八幡宮釣殿","kana":"ありそしょうはちまんぐうつりどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県高岡市横田町3-1-1","lat":36.74985266,"lng":137.00346675,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"16 － 0076","desc":"桁行３間，梁間２間の規模で，南北棟の銅板葺で，柱を角柱とし，組物を置かずに直接桁を受ける。柱間を蔀戸とし，内側に御簾をかける。幣殿と床高を揃え，両側面に縁と高欄を設ける。本殿と幣殿，拝殿をつなぐ空間として境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005270"},{"id":"00005271","register_sub_id":"101","register_pk":"106259","name":"有礒正八幡宮拝殿及び幣殿","kana":"ありそしょうはちまんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県高岡市横田町3-1-1","lat":36.74975352,"lng":137.00341909,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"16 － 0077","desc":"拝殿は１室で，正側面の各間に板戸を建て込み，正面に向拝を付ける。幣殿は一段高い板敷の床とし，左右に翼室を張出す。屋根は両殿を一体化し，八棟造，銅板葺とし，棟に千木，鰹木を置く。社殿の正面を構成し，伝統技法を用いつつ変化に富んだ外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005271"},{"id":"00005269","register_sub_id":"101","register_pk":"106257","name":"有礒正八幡宮本殿","kana":"ありそしょうはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市横田町3-1-1","lat":36.74990742,"lng":137.00349609,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"16 － 0075","desc":"桁行２間半，梁間２間半の規模で，屋根は東西棟の入母屋造の前後に千鳥破風を付して銅板葺とし，棟に千木と鰹木を置く。組物は拳鼻付の平三斗で中備に蟇股を置き，軒は二軒繁垂木とする。正面及び両側面に縁と高欄を廻し，両側面に脇障子を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005269"},{"id":"00011674","register_sub_id":"101","register_pk":"210690","name":"櫟原神社一の鳥居","kana":"いちはらじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768409,"lng":137.340344,"geo_status":"db","era":"安政7年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"石造、間口4.6m、高さ4.5m","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"16-0130","desc":"境内西寄りに置かれた石造明神鳥居。拝殿へは矩折れに続く。間口四・六メートル、高さ四・五メートルの規模で、内転びの柱に貫を通し、その中央には額束を建てる。柱頭には台輪を載せて笠木・島木を受けている。北陸街道沿いの歴史的景観をいまに伝える鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011674"},{"id":"00011675","register_sub_id":"101","register_pk":"210691","name":"櫟原神社二の鳥居","kana":"いちはらじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768535,"lng":137.34035,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造、間口3.5m、高さ3.9m","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"16-0131","desc":"一の鳥居を入って矩折れに進み、拝殿を望む方向に建つ石造鳥居。間口三・五メートル、高さ三・九メートルの規模で、貫の両端を柱の外に延ばさない中山鳥居である。均整のとれた鳥居で、滑川旧市街地の東端部にあって、拝殿前の境内景観を整える鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011675"},{"id":"00011673","register_sub_id":"101","register_pk":"210689","name":"櫟原神社拝殿","kana":"いちはらじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768701,"lng":137.340561,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0129","desc":"入母屋造正背面中央に、切妻造を突出させる構成で、屋根は桟瓦葺。入母屋造部分は前方を拝殿、後方を薬殿と称し、背面突出部は前方を幣殿、奥を祭文殿とする。祭文殿は床高を上げ、前面に木階三級を付す。独特の構成を取る拝所建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011673"},{"id":"00011672","register_sub_id":"101","register_pk":"210688","name":"櫟原神社本殿","kana":"いちはらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768838,"lng":137.340701,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.0㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0128","desc":"櫟原神社は滑川旧市街地の東端部に位置する。石垣を設けた高い位置に建つ切妻造平入の一間社で、屋根は銅板葺。正面に唐破風屋根の向拝を設け、三方に切目縁を廻らし高欄、脇障子を設ける。総欅造りで、井波の彫刻師の手になる脇障子などの彫刻も質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011672"}];
